HEXAGRAMS = {
    "乾為天": {"num": 1, "reading": "けんいてん", "upper": "乾", "lower": "乾", "summary": "天そのもの。力が満ち、はじまりと前進にふさわしいとき。ただし正しさを保てば通る。", "keywords": ["創造", "前進", "剛健"], "lines": [{"name": "初九", "text": "潜龍、用うる勿れ。", "meaning": "まだ淵にひそむ龍。力はあっても、表に出る時ではない、いちばん下の段階。"}, {"name": "九二", "text": "見龍田に在り。大人を見るに利ろし。", "meaning": "龍が地上に姿を現した。芽が出て、人の目に触れはじめる段階。"}, {"name": "九三", "text": "君子終日乾乾し、夕べに惕若たり。厲うけれど咎无し。", "meaning": "一日中はげみ、夜も気を緩めない。危ういが、慎めば咎めはない中間の段階。"}, {"name": "九四", "text": "或いは躍りて淵に在り。咎无し。", "meaning": "跳び上がるか、淵にとどまるか。進退を自分で選べる岐路の段階。"}, {"name": "九五", "text": "飛龍天に在り。大人を見るに利ろし。", "meaning": "龍が天を翔ける、最も充実した段階。実力が満ち、周囲とも響き合う。"}, {"name": "上九", "text": "亢龍悔い有り。", "meaning": "昇りつめ、行き過ぎた龍。これ以上はなく、退くことを忘れた段階。"}], "yong": {"name": "用九", "text": "群龍首无きを見る。吉。", "meaning": "六爻すべてが動く特別な形。先頭を争わない龍の群れ。剛をもって、なお柔を保つとき。"}},
    "坤為地": {"num": 2, "reading": "こんいち", "upper": "坤", "lower": "坤", "summary": "大地のように受けとめ、育てるとき。先に立つより、従い支える側に徳がある。", "keywords": ["受容", "柔順", "育成"], "lines": [{"name": "初六", "text": "霜を履む、堅冰至る。", "meaning": "霜を踏むころには、やがて固い氷が来る。小さな兆しが大きな帰結を呼ぶ、いちばん下の段階。"}, {"name": "六二", "text": "直、方、大なり。習わずして利ろしからざる无し。", "meaning": "まっすぐで、四角く、おおらか。作為せずとも自然に正しく運ぶ、地の徳が満ちた段階。"}, {"name": "六三", "text": "章を含みて貞にすべし。或いは王事に従うも、成すこと无くして終わり有り。", "meaning": "美点を内に秘め、控えめに保つとき。手柄を急がず人を支えれば、よい終わりが来る段階。"}, {"name": "六四", "text": "嚢を括る。咎も无く誉れも无し。", "meaning": "袋の口を固く結ぶように、言葉も振る舞いも慎むとき。誉められないが咎められもしない段階。"}, {"name": "六五", "text": "黄裳、元いに吉なり。", "meaning": "中庸と従順を表す黄の裳をまとう。控えめな徳が中心に座り、大いに吉となる段階。"}, {"name": "上六", "text": "龍、野に戦う。其の血玄黄なり。", "meaning": "陰が極まり、龍が野で相争う。受容が行き過ぎ、ついにぶつかり傷つく段階。"}], "yong": {"name": "用六", "text": "永貞に利ろし。", "meaning": "六爻すべてが動く特別な形。柔の徳を、末永く正しく持ち続けるとき。"}},
    "水雷屯": {"num": 3, "reading": "すいらいちゅん", "upper": "坎", "lower": "震", "summary": "産みの苦しみ。物事が始まろうとして、まだ固く動きにくい難産のとき。", "keywords": ["始動の難", "停滞", "助力"], "lines": [{"name": "初九", "text": "磐桓たり。居て貞しきに利ろし。侯を建つるに利ろし。", "meaning": "進もうとして進めず、その場にとどまる。基盤と助け手を定めるべき、はじまりの段階。"}, {"name": "六二", "text": "屯如邅如たり。馬に乗りて班如たり。寇するに匪ず、婚媾せんとす。女子貞にして字せず、十年にして乃ち字す。", "meaning": "進もうとして足踏みする。敵ではなく縁談だが、今は応じず、時を経てようやく結ばれる悩み多い段階。"}, {"name": "六三", "text": "鹿を逐うに虞人无し。ただ林中に入るのみ。君子は幾を見て、舍くに如かず。往けば吝なり。", "meaning": "案内なしに鹿を追い、深い林に迷い込む。見込みなく突き進めば悔いる段階。"}, {"name": "六四", "text": "馬に乗りて班如たり。婚媾を求めて往く。吉にして利ろしからざる无し。", "meaning": "いったん足踏みするが、よき相手を求めて進めば結ばれる。迷いが晴れて動ける段階。"}, {"name": "九五", "text": "其の膏を屯ます。小貞なれば吉、大貞なれば凶。", "meaning": "恵みを十分に施せず力が滞る。小さく構えれば吉、大きく構えれば凶という段階。"}, {"name": "上六", "text": "馬に乗りて班如たり。泣血漣如たり。", "meaning": "進むことも引くこともできず、血の涙を流す。行き詰まりが極まった段階。"}]},
    "山水蒙": {"num": 4, "reading": "さんすいもう", "upper": "艮", "lower": "坎", "summary": "物事がまだ覆われて見えない、未熟と学びのとき。教えは求める側から始まる。", "keywords": ["未熟", "学び", "啓発"], "lines": [{"name": "初六", "text": "蒙を発く。用て人を刑するに利ろし。桎梏を説くも、以て往けば吝なり。", "meaning": "暗さ・未熟を啓くはじめ。けじめを示して正すのは良いが、甘やかして放てば悔いる段階。"}, {"name": "九二", "text": "蒙を包む。吉なり。婦を納るるに吉。子、家を克くす。", "meaning": "未熟な者を包み込んで導く。寛容さが実を結び、家を治められる段階。"}, {"name": "六三", "text": "女を取る用うる勿れ。金夫を見て躬を有たず。利ろしき攸无し。", "meaning": "目先の利に惹かれて自分を見失う。軽々しく結べば益がない段階。"}, {"name": "六四", "text": "蒙に困しむ。吝なり。", "meaning": "暗さの中に閉じこもり、教えにも触れられない。孤立して伸び悩む段階。"}, {"name": "六五", "text": "童蒙なり。吉なり。", "meaning": "子どものように素直に教えを受ける。へりくだって学ぶ、最も伸びる段階。"}, {"name": "上九", "text": "蒙を撃つ。寇と為るに利ろしからず、寇を禦ぐに利ろし。", "meaning": "行き過ぎた暗さを断つとき。攻め立てるのは害、守り正すのが益という段階。"}]},
    "水天需": {"num": 5, "reading": "すいてんじゅ", "upper": "坎", "lower": "乾", "summary": "前に危険があり、待つとき。あせらず時を待てば、誠は必ず通る。", "keywords": ["待機", "信", "機を待つ"], "lines": [{"name": "初九", "text": "郊に需つ。恒を用うるに利ろし。咎无し。", "meaning": "危険からまだ遠い郊外で待つ。動かず常を保てば咎めのない、いちばん下の段階。"}, {"name": "九二", "text": "沙に需つ。小しく言有れども、終には吉なり。", "meaning": "危険に少し近づいた砂地で待つ。多少の口さがない声はあるが、終わりは吉の段階。"}, {"name": "九三", "text": "泥に需つ。寇の至るを致す。", "meaning": "危険のすぐ際、泥の中で待つ。油断すれば災いを招きかねない、際どい段階。"}, {"name": "六四", "text": "血に需つ。穴より出づ。", "meaning": "傷つく危地に身を置きながらも、穴から抜け出る。難を従順に切り抜ける段階。"}, {"name": "九五", "text": "酒食に需つ。貞しくして吉なり。", "meaning": "酒食を楽しみ、ゆとりを持って待つ。正しさを保てば吉という、充実の段階。"}, {"name": "上六", "text": "穴に入る。速かれざる客三人来たる有り。之を敬すれば終に吉なり。", "meaning": "行き詰まって穴に入るが、招かざる客が訪れる。敬えば最後は吉となる段階。"}]},
    "天水訟": {"num": 6, "reading": "てんすいしょう", "upper": "乾", "lower": "坎", "summary": "争い・もめごとのとき。理があっても、争いを最後まで押し通すと凶。", "keywords": ["争訟", "対立", "和解"], "lines": [{"name": "初六", "text": "事とする所を永くせず。小しく言有れども、終には吉なり。", "meaning": "争いを長引かせず、早めに引く。多少の言い分はあれど、終わりは吉の段階。"}, {"name": "九二", "text": "訟に克たず。帰りて逋る。其の邑人三百戸なれば、眚无し。", "meaning": "争っても勝てず、退いて身を隠す。分をわきまえ小さく構えれば災いを免れる段階。"}, {"name": "六三", "text": "旧き徳に食む。貞なれば厲うけれど、終には吉なり。或いは王事に従うも、成すこと无し。", "meaning": "昔からの分を守って暮らす。危ういが正しさを保てば吉、功は人に譲る段階。"}, {"name": "九四", "text": "訟に克たず。復りて命に即き、渝りて安貞なれば吉なり。", "meaning": "争っても通らず、心を改めて天命を受け入れる。落ち着けば吉に転じる段階。"}, {"name": "九五", "text": "訟う。元いに吉なり。", "meaning": "公正な裁きによって争いが正しく収まる。理が通り、大いに吉となる段階。"}, {"name": "上九", "text": "或いは之に鞶帯を錫う。朝を終うるまでに、三たび之を褫わる。", "meaning": "争って得た栄誉も、一朝のうちに何度も剥ぎ取られる。勝っても続かない段階。"}]},
    "地水師": {"num": 7, "reading": "ちすいし", "upper": "坤", "lower": "坎", "summary": "軍隊を動かすとき。多くを率いるには、正しさと信頼ある指導者が要る。", "keywords": ["統率", "規律", "大義"], "lines": [{"name": "初六", "text": "師は律を以て出づ。否らざれば臧きも凶なり。", "meaning": "軍は規律をもって動き出す。秩序を欠けば、結果が良くても凶という出発の段階。"}, {"name": "九二", "text": "師に在りて中す。吉にして咎无し。王三たび命を錫う。", "meaning": "軍の中心にあって偏らず指揮する。信頼を得て重ねて任される、要となる段階。"}, {"name": "六三", "text": "師、或いは尸を輿す。凶なり。", "meaning": "統率が乱れ、屍を車に乗せて帰るような敗れ。力不足の者が前に出て破れる段階。"}, {"name": "六四", "text": "師、左次す。咎无し。", "meaning": "勝ち目のない戦いを避け、退いて陣を構える。賢く引けば咎めのない段階。"}, {"name": "六五", "text": "田に禽有り。言を執るに利ろし。咎无し。長子は師を帥い、弟子は尸を輿す。貞なれども凶なり。", "meaning": "害をなす相手には大義をもって当たる。任せるは経験ある者、未熟に委ねれば凶の段階。"}, {"name": "上六", "text": "大君、命有り。国を開き家を承く。小人は用うる勿れ。", "meaning": "戦いが収まり、功に応じて報いる論功行賞のとき。徳なき者を用いてはならない段階。"}]},
    "水地比": {"num": 8, "reading": "すいちひ", "upper": "坎", "lower": "坤", "summary": "親しみ、寄り添うとき。心から結ばれる相手を見極めれば吉。", "keywords": ["親和", "結束", "信頼"], "lines": [{"name": "初六", "text": "孚有りて之に比す。咎无し。孚有りて缶に盈つ。終には来たりて他の吉有り。", "meaning": "誠をもって人と親しみ寄り添う。真心が器に満ちるように、思わぬ吉が訪れる始まりの段階。"}, {"name": "六二", "text": "之に比するに内よりす。貞しくして吉なり。", "meaning": "内側から、心から進んで親しむ。へつらいでなく自分の芯から結ぶ、正しく吉の段階。"}, {"name": "六三", "text": "之に比するに人に匪ず。", "meaning": "親しむべきでない相手と結んでしまう。人選を誤り、寄る辺を失いかねない段階。"}, {"name": "六四", "text": "外よりして之に比す。貞しくして吉なり。", "meaning": "外に向かって、賢明な相手に進んで従い親しむ。正しく結べば吉となる段階。"}, {"name": "九五", "text": "比を顕かにす。王、三駆して前の禽を失う。邑人誡めず。吉なり。", "meaning": "親しみを公明正大に示す。去る者は追わず来る者は強いない、寛やかな中心の段階。"}, {"name": "上六", "text": "之に比するに首无し。凶なり。", "meaning": "親しみに肝心の始まり・芯がない。出遅れ、より所を欠いて結べない凶の段階。"}]},
    "風天小畜": {"num": 9, "reading": "ふうてんしょうちく", "upper": "巽", "lower": "乾", "summary": "小さくとどめ、蓄えるとき。大きな力をいったん柔らかく押さえる段階。", "keywords": ["小さな蓄え", "抑制", "準備"], "lines": [{"name": "初九", "text": "復りて道よりす。何の咎あらん。吉なり。", "meaning": "行きすぎず、自分の本来の道に立ち返る。咎なく吉の、いちばん下の段階。"}, {"name": "九二", "text": "牽かれて復る。吉なり。", "meaning": "仲間に促され、ともに本道へ戻る。独走せず連れ立って退く、吉の段階。"}, {"name": "九三", "text": "輿、輻を説く。夫妻反目す。", "meaning": "車の輻が外れて進めない。身近な間でも食い違いが生じる、止められる段階。"}, {"name": "六四", "text": "孚有り。血去り惕れ出づ。咎无し。", "meaning": "誠を尽くすことで、危うさも恐れも遠ざかる。和をもって難を解く、咎なき段階。"}, {"name": "九五", "text": "孚有りて攣如たり。富を以て其の隣とす。", "meaning": "誠でしっかり手を取り合い、富を分かち合う。信頼で人を引き寄せる、充実の段階。"}, {"name": "上九", "text": "既に雨ふり既に処る。徳を尚びて載つ。婦は貞なれば厲うし。月、望に幾し。君子征けば凶なり。", "meaning": "蓄えが満ちて雨が降り、ひとまず収まる。満月寸前、これ以上進めば凶という極まりの段階。"}]},
    "天澤履": {"num": 10, "reading": "てんたくり", "upper": "乾", "lower": "兌", "summary": "虎の尾を踏むような危うい道を、礼をもって歩むとき。慎めば噛まれない。", "keywords": ["礼", "慎重", "実践"], "lines": [{"name": "初九", "text": "素もて履み往く。咎无し。", "meaning": "飾らず、ありのままの素朴さで進む。分を守って歩む、咎なき始まりの段階。"}, {"name": "九二", "text": "履むこと坦坦たり。幽人は貞にして吉なり。", "meaning": "道は平らかで歩みやすい。人目を求めず静かに正しくある者が吉の段階。"}, {"name": "六三", "text": "眇にして能く視、跛にして能く履む。虎の尾を履む。人を咥う。凶なり。武人、大君と為る。", "meaning": "わずかな力で大を望み、虎の尾を踏んで噛まれる。分不相応に逸る、危うい凶の段階。"}, {"name": "九四", "text": "虎の尾を履む。愬愬たれば、終には吉なり。", "meaning": "虎の尾を踏むほどの危地でも、おそれ慎めば最後は吉となる段階。"}, {"name": "九五", "text": "夬として履む。貞なれども厲うし。", "meaning": "決然と踏み切って進む。正しくとも独断は危うさを伴う、強さゆえの段階。"}, {"name": "上九", "text": "履むを視て祥を考う。其の旋ること元なれば、吉なり。", "meaning": "これまでの歩みを振り返り、吉凶を見定める。一巡りが全うされていれば大吉の段階。"}]},
    "地天泰": {"num": 11, "reading": "ちてんたい", "upper": "坤", "lower": "乾", "summary": "天地が交わり、よく通じる泰平のとき。陽が伸び、物事が和合する。", "keywords": ["安泰", "調和", "繁栄"], "lines": [{"name": "初九", "text": "茅を抜くに茹たり。其の彙と以にす。征けば吉なり。", "meaning": "茅を引けば根がつながって抜けるように、仲間と連れ立って進む。動いて吉の始まりの段階。"}, {"name": "九二", "text": "荒を包ね、馮河を用い、遐きを遺れず、朋亡う。中行に尚う。", "meaning": "荒れた者をも包み、果敢に川を渉り、遠きも見捨てず、徒党に偏らない。中庸を尊ぶ要の段階。"}, {"name": "九三", "text": "平らかにして陂かざる无く、往きて復らざる无し。艱んじて貞なれば咎无し。其の孚を恤うる勿れ。食に福有り。", "meaning": "平らなものはやがて傾き、行ったものは必ず還る。盛りに転機の影が差す、心しておく段階。"}, {"name": "六四", "text": "翩翩たり。富まずして其の隣と以にす。戒めずして孚あり。", "meaning": "ひらひらと下り、富をひけらかさず隣人と連なる。誠で自然に集まる、和らぐ段階。"}, {"name": "六五", "text": "帝乙、妹を帰がしむ。以て祉い、元いに吉なり。", "meaning": "高貴な者がへりくだって縁を結ぶ。身分を誇らず和合する、大いに吉の段階。"}, {"name": "上六", "text": "城、隍に復る。師を用うる勿れ。邑より命を告ぐ。貞なれども吝なり。", "meaning": "城壁が崩れて堀に還る、泰平が傾くとき。力で抗わず、身近を整えるしかない段階。"}]},
    "天地否": {"num": 12, "reading": "てんちひ", "upper": "乾", "lower": "坤", "summary": "天地が交わらず、塞がり通じないとき。志ある者には不利。", "keywords": ["閉塞", "不通", "忍耐"], "lines": [{"name": "初六", "text": "茅を抜くに茹たり。其の彙と以にす。貞しくして吉。亨る。", "meaning": "仲間と連なって退く。塞がりの始まりに、同じ志の者と身を慎み正しくあれば吉の段階。"}, {"name": "六二", "text": "包承す。小人は吉、大人は否なり。亨る。", "meaning": "上に取り入りへつらう小人は通るが、大人はその流れに乗らず塞がりを保つ段階。"}, {"name": "六三", "text": "包羞す。", "meaning": "不相応な企てを内に抱え、やがて恥を招く。分を超えて無理をする危うい段階。"}, {"name": "九四", "text": "命有れば咎无し。疇、祉に離く。", "meaning": "塞がりが転じ始める。天の時を得て動けば咎なく、仲間とともに福を分かつ段階。"}, {"name": "九五", "text": "否を休む。大人は吉なり。其れ亡びなん其れ亡びなんと、苞桑に繋ぐ。", "meaning": "塞がりを収めにかかる充実の段階。なお滅びぬかと用心し、根に繋ぎ留めて安んじる。"}, {"name": "上九", "text": "否を傾く。先には否がり後には喜ぶ。", "meaning": "塞がりがついに覆り、通じる方へ転じる。苦しみが終わり喜びに変わる極まりの段階。"}]},
    "天火同人": {"num": 13, "reading": "てんかどうじん", "upper": "乾", "lower": "離", "summary": "人と同じくし、志を共にするとき。広く公平に集えば、大事も渡れる。", "keywords": ["協同", "公平", "連帯"], "lines": [{"name": "初九", "text": "人に同じくするに門に于いてす。咎无し。", "meaning": "門を出てすぐ、広く開かれた場で人と志を同じくする。私心なく公平な、始まりの段階。"}, {"name": "六二", "text": "人に同じくするに宗に于いてす。吝なり。", "meaning": "身内・派閥の中だけで結ぶ。狭い仲間内に偏り、視野を失う、悔いの残る段階。"}, {"name": "九三", "text": "戎を莽に伏せ、其の高陵に升る。三歳まで興らず。", "meaning": "疑心から兵を伏せ、高みに登って様子をうかがう。打って出られず長く膠着する段階。"}, {"name": "九四", "text": "其の墉に乗る。攻むるに克たず。吉なり。", "meaning": "攻めようと城壁に乗るが、攻めきれず思いとどまる。引き返すことで吉に転じる段階。"}, {"name": "九五", "text": "人に同じくするに、先には號咷して後に笑う。大師克ちて相い遇う。", "meaning": "隔てられて泣き叫ぶが、ついに障害を破って結ばれ笑う。試練を越えて再会する段階。"}, {"name": "上九", "text": "人に同じくするに郊に于いてす。悔い无し。", "meaning": "人里離れた郊外で結ぶ。広い交わりには至らないが、悔いのない静かな終わりの段階。"}]},
    "火天大有": {"num": 14, "reading": "かてんたいゆう", "upper": "離", "lower": "乾", "summary": "大いに有つ、豊かさが満ちるとき。明るさが上に立ち、多くを治める。", "keywords": ["豊かさ", "所有", "寛容"], "lines": [{"name": "初九", "text": "害に交わること无し。咎に匪ず。艱めば則ち咎无し。", "meaning": "豊かさの始まり。まだ害に触れていない。驕らず難を思えば咎のない、いちばん下の段階。"}, {"name": "九二", "text": "大車以て載す。往く攸有り。咎无し。", "meaning": "大きな車に荷を満載するように、十分な力で物事を担える。進んで事を成せる段階。"}, {"name": "九三", "text": "公、用て天子に亨す。小人は克わず。", "meaning": "豊かさを公のために天子へ捧げる。器の大きい者は通じ、私する小人には及ばない段階。"}, {"name": "九四", "text": "其の彭たること匪ず。咎无し。", "meaning": "豊かさを誇示せず、出すぎを抑える。盛りの傍らで身を慎めば咎のない段階。"}, {"name": "六五", "text": "厥の孚、交如たり。威如たれば吉なり。", "meaning": "誠が上下に通い合う中心の段階。柔らかな誠に加え、適度な威厳を保てば吉となる。"}, {"name": "上九", "text": "天よりこれを祐く。吉にして利ろしからざる无し。", "meaning": "天が助ける、大有の極み。誠と謙を保つ者に、天の助けが満ちる最良の段階。"}]},
    "地山謙": {"num": 15, "reading": "ちざんけん", "upper": "坤", "lower": "艮", "summary": "高い山が地の下にある、へりくだりのとき。謙虚な者は最後まで通る。", "keywords": ["謙虚", "控えめ", "徳"], "lines": [{"name": "初六", "text": "謙謙たる君子。用て大川を渉る。吉なり。", "meaning": "どこまでもへりくだる君子。謙虚さを携えれば、大きな困難も渡れる、始まりの段階。"}, {"name": "六二", "text": "謙を鳴らす。貞しくして吉。", "meaning": "内なる謙虚さが自然と外に表れる。飾りでなく身についた謙が、正しく吉となる段階。"}, {"name": "九三", "text": "労謙す。君子は終わり有り。吉なり。", "meaning": "功があってもなお謙る。働き者でへりくだる君子は、よい終わりを全うする中心の段階。"}, {"name": "六四", "text": "利ろしからざる无し。謙を撝ぐ。", "meaning": "すべてに利あり。へりくだりを発揮し、上を敬い下を導く。釣り合いの取れた段階。"}, {"name": "六五", "text": "富まずして其の隣を以う。用て侵伐するに利ろし。利ろしからざる无し。", "meaning": "富を誇らずとも人がついてくる。必要なら毅然と正す。謙の中に芯を持つ段階。"}, {"name": "上六", "text": "謙を鳴らす。用て師を行り、邑国を征するに利ろし。", "meaning": "謙の極み。なお内に治めきれぬものがあり、まず自らの足元を正すべき段階。"}]},
    "雷地豫": {"num": 16, "reading": "らいちよ", "upper": "震", "lower": "坤", "summary": "雷が地から出る、よろこびと勢いのとき。備えと和があれば動きが通る。", "keywords": ["悦び", "勢い", "備え"], "lines": [{"name": "初六", "text": "豫を鳴らす。凶なり。", "meaning": "喜びや勢いを得意げに鳴らし立てる。浮かれて自ら吹聴し、災いを招く、いちばん下の段階。"}, {"name": "六二", "text": "石よりも介し。日を終えず。貞しくして吉。", "meaning": "石のように固く節を守り、機を見れば即座に動く。浮かれに流されず正しく吉の段階。"}, {"name": "六三", "text": "盱して豫しむ。悔ゆ。遅ければ悔い有り。", "meaning": "上を見上げて取り入り楽しむ。自立を欠き、ぐずぐずすれば悔いを重ねる段階。"}, {"name": "九四", "text": "豫に由る。大いに得る有り。疑う勿れ。朋盍ち簪まる。", "meaning": "喜びと勢いの源となる中心の段階。疑わず誠を尽くせば、仲間が集まり大きく得る。"}, {"name": "六五", "text": "貞しけれど疾あり。恒に死せず。", "meaning": "安逸に押されて力を振るえず、持病のように停滞する。それでも保てば滅びない段階。"}, {"name": "上六", "text": "冥豫す。成りて渝ること有り。咎无し。", "meaning": "喜びに溺れ、分別を失う極み。だが過ちに気づいて改めれば、咎を免れる段階。"}]},
    "澤雷随": {"num": 17, "reading": "たくらいずい", "upper": "兌", "lower": "震", "summary": "時に随い、人に従うとき。正しく従えば大いに通り、咎はない。", "keywords": ["随順", "適応", "信頼"], "lines": [{"name": "初九", "text": "官に渝ること有り。貞しくして吉。門を出でて交われば功有り。", "meaning": "立場や考えを改めて新しい流れに従う。内に閉じず外と交われば功のある、始まりの段階。"}, {"name": "六二", "text": "小子に係る。丈夫を失う。", "meaning": "目先の小さなものに執着し、本当に頼るべき相手を失う。随う相手を誤る段階。"}, {"name": "六三", "text": "丈夫に係る。小子を失う。随いて求めて得る有り。貞に居るに利ろし。", "meaning": "頼るべき相手を選び、小さな執着を手放す。正しく随えば求めて得られる段階。"}, {"name": "九四", "text": "随いて獲ること有り。貞なれども凶なり。孚有りて道に在り、以て明らかなれば、何の咎あらん。", "meaning": "従われ慕われて得るものが多い段階。だが私すれば凶。誠と道理を明らかに保てば咎なし。"}, {"name": "九五", "text": "嘉きに孚あり。吉なり。", "meaning": "善きもの・善き人を心から信じて従う、充実の中心の段階。誠が嘉に通じて吉となる。"}, {"name": "上六", "text": "之を拘係し、乃ち従いて之を維ぐ。王、用て西山に亨す。", "meaning": "固く結ばれ、離れがたく随い従う随の極み。誠が神明にまで通じる段階。"}]},
    "山風蠱": {"num": 18, "reading": "さんぷうこ", "upper": "艮", "lower": "巽", "summary": "器に虫がわくように、長年の乱れや澱みを正すとき。立て直しの好機。", "keywords": ["再建", "立て直し", "刷新"], "lines": [{"name": "初六", "text": "父の蠱を幹む。子有れば、考咎无し。厲うけれど終には吉なり。", "meaning": "父祖の代から積もった乱れを正し始める。受け継いだ澱みに手をつける、始まりの段階。"}, {"name": "九二", "text": "母の蠱を幹む。貞にすべからず。", "meaning": "柔らかな相手の乱れを正すとき。強引に押し通さず、加減して整えるべき段階。"}, {"name": "九三", "text": "父の蠱を幹む。小しく悔い有れど、大いなる咎无し。", "meaning": "改革に勢いがやや過ぎ、小さな悔いは残る。それでも大過には至らない中間の段階。"}, {"name": "六四", "text": "父の蠱を裕にす。往けば吝を見る。", "meaning": "乱れを正さず、なあなあに見過ごす。手をこまねくほど後で悔いる段階。"}, {"name": "六五", "text": "父の蠱を幹む。用て誉れあり。", "meaning": "受け継いだ乱れを立派に正し、誉れを得る中心の段階。徳をもって改革を成す。"}, {"name": "上九", "text": "王侯に事えず。其の事を高尚にす。", "meaning": "世の役職を離れ、志を高く保つ蠱の極み。立て直しを終え、自らの道を尊ぶ段階。"}]},
    "地澤臨": {"num": 19, "reading": "ちたくりん", "upper": "坤", "lower": "兌", "summary": "上から臨み、近づき育てるとき。勢いは増すが、盛りには衰えの兆しも。", "keywords": ["臨む", "成長", "時機"], "lines": [{"name": "初九", "text": "咸じて臨む。貞しくして吉。", "meaning": "心を通わせて人に臨み近づく。誠の感応で導き始める、正しく吉の段階。"}, {"name": "九二", "text": "咸じて臨む。吉にして利ろしからざる无し。", "meaning": "誠の感応で人に臨み、勢いに乗って進む。何をしても通じる、充実した段階。"}, {"name": "六三", "text": "甘んじて臨む。利ろしき攸无し。既に之を憂うれば、咎无し。", "meaning": "甘い態度で安易に臨む。なれ合いに利はないが、危うさを憂い改めれば咎を免れる段階。"}, {"name": "六四", "text": "至りて臨む。咎无し。", "meaning": "真心を尽くしてぴたりと寄り添い臨む。上にありながら下と親しく交わる、咎なき段階。"}, {"name": "六五", "text": "知をもって臨む。大君の宜しきなり。吉なり。", "meaning": "知恵をもって人に臨み、適材に任せる中心の段階。賢明な大君の振る舞いで吉となる。"}, {"name": "上六", "text": "敦くして臨む。吉にして咎无し。", "meaning": "手厚い真心で人に臨む臨の極み。驕らず篤実に下を遇する、吉にして咎なき段階。"}]},
    "風地観": {"num": 20, "reading": "ふうちかん", "upper": "巽", "lower": "坤", "summary": "高きから観て、また下から仰ぎ見るとき。誠を整えれば、見る者も改まる。", "keywords": ["観察", "省察", "示範"], "lines": [{"name": "初六", "text": "童観す。小人は咎无し。君子は吝なり。", "meaning": "子どものように浅くしか観られない、いちばん下の段階。凡人なら無難だが、上に立つ者には恥。"}, {"name": "六二", "text": "闚観す。女の貞に利ろし。", "meaning": "戸の隙間からのぞき見るように、狭く偏った観方。控えめにはよいが、広く見るには足りぬ段階。"}, {"name": "六三", "text": "我が生を観て、進退す。", "meaning": "自分のこれまでの歩みを省みて、進むか退くかを決める。自己を省察する段階。"}, {"name": "六四", "text": "国の光を観る。用て王に賓たるに利ろし。", "meaning": "国の輝き・優れたものを間近に観る。見識を広げ、世に用いられるにふさわしい段階。"}, {"name": "九五", "text": "我が生を観る。君子なれば咎无し。", "meaning": "上に立つ者として、自らの生き方を観て省みる中心の段階。徳を保てば咎なし。"}, {"name": "上九", "text": "其の生を観る。君子なれば咎无し。", "meaning": "一歩引いて、自他の生き方を広く観る観の極み。高みから省みて徳を保てば咎なき段階。"}]},
    "火雷噬嗑": {"num": 21, "reading": "からいぜいこう", "upper": "離", "lower": "震", "summary": "噛んで合わせる。間にある障害を断ち切って通すとき。曖昧を許さない。", "keywords": ["決断", "障害除去", "断行"], "lines": [{"name": "初九", "text": "校を屨きて趾を滅す。咎无し。", "meaning": "足かせをはめられ、軽い罰で戒められる。小さなうちに正される、始まりの段階。"}, {"name": "六二", "text": "膚を噬みて鼻を滅す。咎无し。", "meaning": "柔らかい肉に深く噛みつくように、勢いよく障害を処す。やや過ぎても咎のない段階。"}, {"name": "六三", "text": "腊肉を噬みて毒に遇う。小しく吝なれど、咎无し。", "meaning": "古い干し肉を噛んで毒に当たるように、こじれた問題に手こずる。多少の悔いはある段階。"}, {"name": "九四", "text": "乾胏を噬みて金矢を得。艱貞に利ろし。吉なり。", "meaning": "骨つきの干し肉を噛み砕き、金の矢を得る。困難な障害を断ち、剛直さを得る要の段階。"}, {"name": "六五", "text": "乾肉を噬みて黄金を得。貞しけれど厲うし。咎无し。", "meaning": "干し肉を噛んで黄金を得る。中庸と正しさで裁く中心の段階。危うさを忘れねば咎なし。"}, {"name": "上九", "text": "校を何いて耳を滅す。凶なり。", "meaning": "首かせをはめられ耳まで覆われる、噬嗑の極み。戒めを聞かず罪を重ねた凶の段階。"}]},
    "山火賁": {"num": 22, "reading": "さんかひ", "upper": "艮", "lower": "離", "summary": "山のふもとを火が照らす、飾り・装いのとき。彩りは添えるが、過ぎれば実を失う。", "keywords": ["装飾", "美", "節度"], "lines": [{"name": "初九", "text": "其の趾を賁る。車を舍てて徒す。", "meaning": "足元を飾り、分不相応な車を捨てて歩く。身の丈の素朴さを選ぶ、始まりの段階。"}, {"name": "六二", "text": "其の須を賁る。", "meaning": "あごひげを飾る。自らは主にならず、上に従って共に動き引き立てる、付き従いの段階。"}, {"name": "九三", "text": "賁如たり濡如たり。永貞なれば吉なり。", "meaning": "潤いある飾りに恵まれ、心地よさに包まれる段階。長く正しさを保てば吉となる。"}, {"name": "六四", "text": "賁如たり皤如たり。白馬翰如たり。寇に匪ず、婚媾せんとす。", "meaning": "飾りを捨てて素白に立ち返り、まっすぐ結ぶ相手を求める。疑いが晴れて結ばれる段階。"}, {"name": "六五", "text": "丘園に賁る。束帛戔戔たり。吝なれど、終には吉なり。", "meaning": "華美を離れ、丘や園の質素を尊ぶ中心の段階。倹しさは見劣りするが、終わりは吉となる。"}, {"name": "上九", "text": "白く賁る。咎无し。", "meaning": "飾りをすべて落とし、白く素のままに帰る賁の極み。装いを超えた素朴に至り、咎なき段階。"}]},
    "山地剝": {"num": 23, "reading": "さんちはく", "upper": "艮", "lower": "坤", "summary": "下から削り落とされ、剥がれていくとき。陰が極まり、進むに不利。", "keywords": ["衰退", "剥落", "守り"], "lines": [{"name": "初六", "text": "牀を剝するに足を以てす。貞を蔑にして凶なり。", "meaning": "寝台の脚から削られ始める。崩壊が足元から忍び寄る、いちばん下の凶の段階。"}, {"name": "六二", "text": "牀を剝するに辨を以てす。貞を蔑にして凶なり。", "meaning": "削りが寝台の枠まで及ぶ。崩れが進み、より所を失っていく凶の段階。"}, {"name": "六三", "text": "之を剝す。咎无し。", "meaning": "崩れの流れの中にありながら、上の正しき者に応じて身を保つ。剥落の中で咎を免れる段階。"}, {"name": "六四", "text": "牀を剝するに膚を以てす。凶なり。", "meaning": "削りがついに身に及ぶ。災いが我が身に直接迫る、避けがたい凶の段階。"}, {"name": "六五", "text": "魚を貫く。宮人の寵を以てす。利ろしからざる无し。", "meaning": "魚を一列に貫くように陰を統べ、上の一陽に従い率いる。崩れが転じ、利を得る段階。"}, {"name": "上九", "text": "碩果は食らわれず。君子は輿を得、小人は廬を剝す。", "meaning": "食べ残された大きな果実=最後の一陽。崩れ尽きて再生の種が残る剝の極み。"}]},
    "地雷復": {"num": 24, "reading": "ちらいふく", "upper": "坤", "lower": "震", "summary": "一陽が地の底に還る、回復と再出発のとき。冬至のように光が戻り始める。", "keywords": ["回復", "再起", "還る"], "lines": [{"name": "初九", "text": "遠からずして復る。悔いに祗ること无し。元いに吉なり。", "meaning": "遠くまで行かぬうちに、すぐ本道へ立ち返る。過ちを早く正す、大いに吉の始まりの段階。"}, {"name": "六二", "text": "休く復る。吉なり。", "meaning": "心穏やかに、善き人に倣ってよく立ち返る。素直に復る、吉の段階。"}, {"name": "六三", "text": "頻りに復る。厲うけれど咎无し。", "meaning": "行きつ戻りつ、何度も立ち返る。危うさはあるが、改める限り咎のない段階。"}, {"name": "六四", "text": "中行して独り復る。", "meaning": "周りが迷う中、ただ独り正しい道へ立ち返る。流されず本道に帰る段階。"}, {"name": "六五", "text": "敦く復る。悔い无し。", "meaning": "篤い真心をもって、しっかりと立ち返る中心の段階。深く省みて改め、悔いを残さない。"}, {"name": "上六", "text": "復るに迷う。凶なり。災眚あり。用て師を行れば、終に大敗あり。其の国君に凶ぶ。十年に至るまで征する克わず。", "meaning": "帰るべき時を見失い、迷って戻れない復の極み。過ちを正せず、長く災いを引きずる凶の段階。"}]},
    "天雷无妄": {"num": 25, "reading": "てんらいむぼう", "upper": "乾", "lower": "震", "summary": "偽りなく、天のままにあるとき。作為を捨てれば通る。よこしまには災い。", "keywords": ["誠実", "自然", "無心"], "lines": [{"name": "初九", "text": "无妄なり。往きて吉なり。", "meaning": "偽りなく、まっすぐな心のままに動く。誠で踏み出せば吉となる、始まりの段階。"}, {"name": "六二", "text": "耕さずして穫り、菑かずして畬る。則ち往く攸有るに利ろし。", "meaning": "見返りを当てにせず、なすべきを淡々と行う。結果を計らぬから、進んで利のある段階。"}, {"name": "六三", "text": "无妄の災。或いは之が牛を繋ぐ。行人の得るは、邑人の災なり。", "meaning": "落ち度なく降りかかる災い。繋いだ牛を旅人が奪い、里人が疑われるような、理不尽な段階。"}, {"name": "九四", "text": "貞にすべし。咎无し。", "meaning": "正しさを固く守りさえすればよい段階。誠を保ち動かずにいれば、咎は生じない。"}, {"name": "九五", "text": "无妄の疾。薬する勿れ。喜び有り。", "meaning": "誠を尽くしてなお起こる、いわれのない不調。下手に手を加えず待てば、自ずと癒える段階。"}, {"name": "上九", "text": "无妄なるも行けば眚あり。利ろしき攸无し。", "meaning": "誠であっても、時を弁えず動けば災いを招く无妄の極み。今は進むべきでない段階。"}]},
    "山天大畜": {"num": 26, "reading": "さんてんたいちく", "upper": "艮", "lower": "乾", "summary": "大いに蓄え、力をためるとき。徳と実力を養えば、大事も渡れる。", "keywords": ["大きな蓄え", "鍛錬", "登用"], "lines": [{"name": "初九", "text": "厲うきこと有り。已むに利ろし。", "meaning": "進めば危うい。蓄えの始め、無理に動かず止まるのが利のある、いちばん下の段階。"}, {"name": "九二", "text": "輿、輹を説く。", "meaning": "車軸の留めを自ら外し、進むのをやめる。抑えられて止まるが、損なわれぬ段階。"}, {"name": "九三", "text": "良馬逐う。艱貞に利ろし。日に輿衛を閑えば、往く攸有るに利ろし。", "meaning": "良馬が並んで駆けるように、蓄えが解けて進める段階。日々鍛え備えれば、前へ出て利あり。"}, {"name": "六四", "text": "童牛の牿なり。元いに吉なり。", "meaning": "角の生え初めの子牛に横木をあてるように、勢いを早めに穏やかに抑える。大いに吉の段階。"}, {"name": "六五", "text": "豶豕の牙なり。吉なり。", "meaning": "去勢した猪の牙のように、猛々しさの根を和らげて制する中心の段階。要を押さえて吉。"}, {"name": "上九", "text": "何ぞ天の衢なる。亨る。", "meaning": "蓄えが満ち、天の大道がからりと開ける大畜の極み。力が世に通じ、大いに通る段階。"}]},
    "山雷頤": {"num": 27, "reading": "さんらいい", "upper": "艮", "lower": "震", "summary": "あごの形。養う・養われるとき。何を口にし、何で心身を養うかが問われる。", "keywords": ["養生", "言葉", "節制"], "lines": [{"name": "初九", "text": "爾の霊亀を舍てて、我を観て頤を朶る。凶なり。", "meaning": "自分の中の貴い糧を捨て、人の食を羨んで口を垂らす。自立を失う、凶の始まりの段階。"}, {"name": "六二", "text": "頤に顛る。経に拂る。丘に于いて頤われんとす。征けば凶なり。", "meaning": "養う上下が逆さになり、筋に背いて高きに食を求める。道を外れて動けば凶の段階。"}, {"name": "六三", "text": "頤に拂る。貞なれども凶なり。十年用うる勿れ。利ろしき攸无し。", "meaning": "養いの道に真っ向から背く。欲のままに養われ、長く立ち行かない凶の段階。"}, {"name": "六四", "text": "頤に顛る。吉なり。虎の視ること眈眈、其の欲うこと逐逐たれば、咎无し。", "meaning": "下に養いを求めるが、虎のように真剣に見据え、絶えず誠を尽くせば咎のない段階。"}, {"name": "六五", "text": "経に拂る。貞に居れば吉。大川を渉るべからず。", "meaning": "自ら養う力が足りず常道に背くが、正しく身を処し賢に頼れば吉。大事には進めぬ段階。"}, {"name": "上九", "text": "頤に由る。厲うけれど吉なり。大川を渉るに利ろし。", "meaning": "万人を養う源となる頤の極み。責任は重く危ういが、よく担えば吉、大事も渡れる段階。"}]},
    "澤風大過": {"num": 28, "reading": "たくふうたいか", "upper": "兌", "lower": "巽", "summary": "棟木がしなうほど、負荷が過大なとき。常を越える非常時。", "keywords": ["過重", "非常", "果断"], "lines": [{"name": "初六", "text": "藉くに白茅を用う。咎无し。", "meaning": "供え物の下に白い茅を敷くように、非常時のはじめを慎重に丁寧に扱う。咎なき段階。"}, {"name": "九二", "text": "枯楊、稊を生ず。老夫、其の女妻を得。利ろしからざる无し。", "meaning": "枯れた柳が新芽を吹き、老人が若い妻を得るように、衰えに新たな生気が通う。利のある段階。"}, {"name": "九三", "text": "棟撓む。凶なり。", "meaning": "屋根の棟木がしなりたわむ。負荷に対し剛が過ぎて支えきれず、折れかける凶の段階。"}, {"name": "九四", "text": "棟隆んなり。吉なり。它有れば吝なり。", "meaning": "棟木がしっかり持ち上がり、重みを支えられる吉の段階。ただ他に心を移せば悔いが残る。"}, {"name": "九五", "text": "枯楊、華を生ず。老婦、其の士夫を得。咎も无く誉れも无し。", "meaning": "枯れ柳が花を咲かせるが実は結ばぬように、見栄えはあれど長続きしない、可もなく不可もない段階。"}, {"name": "上六", "text": "過ぎて渉る。頂を滅す。凶なれど、咎无し。", "meaning": "川を渡りきろうと進みすぎ、頭まで水に没する大過の極み。身を捨てても志を貫く段階。"}]},
    "坎為水": {"num": 29, "reading": "かんいすい", "upper": "坎", "lower": "坎", "summary": "水が重なる、繰り返す険難のとき。誠の心を保てば、難の中でも通る。", "keywords": ["険難", "試練", "誠"], "lines": [{"name": "初六", "text": "習坎なり。坎の窞に入る。凶なり。", "meaning": "険難が重なり、穴の中のさらに深い穴に落ち込む。危地に慣れて沈む、凶の始まりの段階。"}, {"name": "九二", "text": "坎に険有り。求めて小しく得。", "meaning": "険難のただ中で身動きが取りにくい。多くは望めず、わずかに求めて得られる段階。"}, {"name": "六三", "text": "来るも之くも坎坎たり。険にして且つ枕む。坎の窞に入る。用うる勿れ。", "meaning": "進んでも退いても険難ばかり。危地に深く入り込み、動けば沈む。動くべきでない段階。"}, {"name": "六四", "text": "樽酒、簋弐、用うるに缶を以てす。約を牖より納る。終に咎无し。", "meaning": "飾らぬ酒と食を素焼きの器で差し出し、誠を率直に通わせる。質素な真心で難を凌ぐ段階。"}, {"name": "九五", "text": "坎盈たず。既に平らかなるに祗る。咎无し。", "meaning": "険難の水がまだ溢れず、ようやく平らになりかける中心の段階。中庸を保てば咎なし。"}, {"name": "上六", "text": "徽纆を係け、叢棘に寘く。三歳まで得ず。凶なり。", "meaning": "縄で縛られ、いばらの中に置かれて長く抜け出せない坎の極み。険難に囚われきった凶の段階。"}]},
    "離為火": {"num": 30, "reading": "りいか", "upper": "離", "lower": "離", "summary": "火が重なり明るく照らすとき。何かに付き、明らかにする。正しさに依れば通る。", "keywords": ["明智", "付着", "情熱"], "lines": [{"name": "初九", "text": "履むこと錯然たり。之を敬すれば咎无し。", "meaning": "明るさの出だしで足取りが乱れ交錯する。慎んで敬えば咎を免れる、いちばん下の段階。"}, {"name": "六二", "text": "黄離なり。元いに吉なり。", "meaning": "中庸を表す黄の輝きに付く。明るさが過不足なく整う、大いに吉の中心の段階。"}, {"name": "九三", "text": "日昃くの離なり。缶を鼓して歌わざれば、則ち大耋の嗟あり。凶なり。", "meaning": "日が傾く頃の明るさ。盛りの過ぎゆくを受け入れて楽しめず、老いを嘆けば凶の段階。"}, {"name": "九四", "text": "突如として其れ来如たり。焚如たり、死如たり、棄如たり。", "meaning": "燃え盛る火が突然襲うように、勢いが激しすぎて自らを焼き尽くす。急激に破れる段階。"}, {"name": "六五", "text": "涕を出すこと沱若たり。戚うること嗟若たり。吉なり。", "meaning": "涙を流し憂え嘆く中心の段階。柔弱な身を憂え慎むからこそ、かえって吉に転じる。"}, {"name": "上九", "text": "王、用て出征す。嘉き有り。首を折き、獲るは其の醜に匪ず。咎无し。", "meaning": "明知を世に向け、悪の首魁だけを討って従う者は赦す離の極み。けじめをつけて咎なき段階。"}]},
    "澤山咸": {"num": 31, "reading": "たくざんかん", "upper": "兌", "lower": "艮", "summary": "山の上に澤、感じ合うとき。心が通い、互いに応じる。出会いと感応。", "keywords": ["感応", "共鳴", "縁"], "lines": [{"name": "初六", "text": "其の拇に咸ず。", "meaning": "感応がまだ足の親指にとどまる。心が動き始めたばかりで、表に出ない、いちばん下の段階。"}, {"name": "六二", "text": "其の腓に咸ず。凶なり。居れば吉。", "meaning": "感応がふくらはぎに及び、思わず動き出しそうになる。先走れば凶、留まれば吉の段階。"}, {"name": "九三", "text": "其の股に咸ず。其の随うを執る。往けば吝なり。", "meaning": "感応が股に及び、人に引きずられて動く。自分を持たず付き従えば、悔いる段階。"}, {"name": "九四", "text": "貞しくして吉。悔い亡ぶ。憧憧として往来すれば、朋、爾の思いに従う。", "meaning": "心の感応の要となる段階。正しく構えれば吉。落ち着かず私情で往き来すれば、狭い縁しか応じぬ。"}, {"name": "九五", "text": "其の脢に咸ず。悔い无し。", "meaning": "感応が背に及ぶ。私情に流されず、動じない位置で誠を保つ中心の段階。悔いなし。"}, {"name": "上六", "text": "其の輔・頬・舌に咸ず。", "meaning": "感応が口先・頬・舌にとどまる咸の極み。口先だけで心が伴わない、上滑りの段階。"}]},
    "雷風恒": {"num": 32, "reading": "らいふうこう", "upper": "震", "lower": "巽", "summary": "雷と風、変わらず続く常のとき。久しきを保てば通る。持続の徳。", "keywords": ["持続", "恒常", "継続"], "lines": [{"name": "初六", "text": "浚き恒なり。貞なれども凶なり。利ろしき攸无し。", "meaning": "はじめから深く求めすぎる恒。常を急いで掘り下げ、無理を通せば凶という、いちばん下の段階。"}, {"name": "九二", "text": "悔い亡ぶ。", "meaning": "中庸を得て、行き過ぎを正す。常を保つ力が定まり、悔いが消えていく段階。"}, {"name": "九三", "text": "其の徳を恒にせず。或いは之が羞を承く。貞なれども吝なり。", "meaning": "徳を一定に保てず、心がぐらつく。節操なく揺れて恥を受ける、悔いの残る段階。"}, {"name": "九四", "text": "田して禽无し。", "meaning": "畑違いの場所で獲物を狙うように、いるべき所を外して努める。実りの得られない段階。"}, {"name": "六五", "text": "其の徳を恒にす。貞し。婦人は吉、夫子は凶なり。", "meaning": "一つの徳を守り通す段階。従い支える立場には吉だが、自ら決すべき立場には凶となる。"}, {"name": "上六", "text": "恒を振う。凶なり。", "meaning": "落ち着かず常を揺り動かす恒の極み。終わりまで定まらず、ぐらつき続けて凶の段階。"}]},
    "天山遯": {"num": 33, "reading": "てんざんとん", "upper": "乾", "lower": "艮", "summary": "退き、身を遠ざけるとき。陰が伸びる前に、潔く引けば通る。", "keywords": ["退避", "引き際", "保身"], "lines": [{"name": "初六", "text": "遯の尾なり。厲うし。往く攸有るに用うる勿れ。", "meaning": "退くのに出遅れ、しんがりになる。逃げ遅れて危うい、いちばん下の段階。"}, {"name": "六二", "text": "之を執うるに黄牛の革を用う。説くべきこと莫し。", "meaning": "黄牛の革で固く縛るように、堅い意志で結びを保つ。誰にもほどけぬ堅固な段階。"}, {"name": "九三", "text": "係れる遯なり。疾有りて厲うし。臣妾を畜うに吉なり。", "meaning": "未練に絡まれて退ききれない。煩いがあって危ういが、身近を養うには吉という段階。"}, {"name": "九四", "text": "好める遯なり。君子は吉、小人は否なり。", "meaning": "好むものを抱えながらも、潔く退く。未練を断てる君子は吉、断てぬ小人は凶の段階。"}, {"name": "九五", "text": "嘉き遯なり。貞しくして吉。", "meaning": "時宜にかなった、美しく潔い退き。中正を保って引ける、正しく吉の中心の段階。"}, {"name": "上九", "text": "肥かなる遯なり。利ろしからざる无し。", "meaning": "何の絡みもなく、ゆとりをもって悠々と退く遯の極み。心軽く身を引く、利のある段階。"}]},
    "雷天大壮": {"num": 34, "reading": "らいてんたいそう", "upper": "震", "lower": "乾", "summary": "雷が天に轟く、勢い盛んなとき。力は強いが、正しさを欠けば暴走する。", "keywords": ["強盛", "勢い", "自制"], "lines": [{"name": "初九", "text": "趾に壮んなり。征けば凶なり。孚有り。", "meaning": "足元から勢いづいて突き進もうとする。力任せに進めば凶という、いちばん下の段階。"}, {"name": "九二", "text": "貞しくして吉。", "meaning": "強さを内に抑え、中庸を保つ。勢いを正しく御して吉となる段階。"}, {"name": "九三", "text": "小人は壮を用い、君子は罔を用う。貞なれども厲うし。羝羊藩に触れ、其の角を羸る。", "meaning": "小人は力を振るい、君子は用いない。垣根に角を突っ込んだ雄羊のように、力みが身を縛る段階。"}, {"name": "九四", "text": "貞しくして吉。悔い亡ぶ。藩決けて羸れず。壮んなること大輿の輹に于いてす。", "meaning": "正しく構えれば吉、悔いも消える。垣根が開けて角は絡まず、大車の心棒のように力強く進む段階。"}, {"name": "六五", "text": "羊を易に喪う。悔い无し。", "meaning": "荒ぶる羊（強さ）を、和らげる場所で穏やかに手放す。剛を緩め、悔いの残らぬ段階。"}, {"name": "上六", "text": "羝羊藩に触れ、退くこと能わず遂ぐること能わず。利ろしき攸无し。艱めば則ち吉なり。", "meaning": "垣に角を突っ込んだ雄羊が進退きわまる大壮の極み。突っ張った末に動けなくなる段階。"}]},
    "火地晋": {"num": 35, "reading": "かちしん", "upper": "離", "lower": "坤", "summary": "太陽が地上に昇る、進み栄えるとき。明るく前に出て、認められる。", "keywords": ["前進", "昇進", "栄達"], "lines": [{"name": "初六", "text": "晋如たり摧如たり。貞しくして吉。孚とせられざるも、裕なれば咎无し。", "meaning": "進もうとして阻まれる、昇り始めの段階。まだ信を得られずとも、ゆとりを保てば咎なし。"}, {"name": "六二", "text": "晋如たり愁如たり。貞しくして吉。茲の介福を其の王母に于いて受く。", "meaning": "進みたいのに憂え悩む段階。だが正しさを保てば、やがて上から大きな幸いを受ける。"}, {"name": "六三", "text": "衆允ふ。悔い亡ぶ。", "meaning": "周りの人々が心を合わせて従う。皆の信を得て進む、悔いの消える段階。"}, {"name": "九四", "text": "晋如たること鼫鼠のごとし。貞なれども厲うし。", "meaning": "むささびのように欲深く昇ろうとする。地位に貪欲で、危うさをはらむ段階。"}, {"name": "六五", "text": "悔い亡ぶ。失得恤うる勿れ。往けば吉にして利ろしからざる无し。", "meaning": "中心に進み出て、明るく上に立つ段階。損得にこだわらず進めば、すべて吉となる。"}, {"name": "上九", "text": "其の角に晋む。維れ用て邑を伐つ。厲うけれど吉にして咎无し。貞なれども吝なり。", "meaning": "角の先まで突き進む晋の極み。行き過ぎだが、まず我が身内を正すなら、危うくも咎なき段階。"}]},
    "地火明夷": {"num": 36, "reading": "ちかめいい", "upper": "坤", "lower": "離", "summary": "明るさが地に没し、傷つくとき。才を隠し、苦難の中で正しさを守る。", "keywords": ["韜晦", "受難", "忍耐"], "lines": [{"name": "初九", "text": "明夷、飛ぶに于いて其の翼を垂る。君子行きて、三日食らわず。往く攸有れば、主人言有り。", "meaning": "傷つく時、飛ぶ鳥が翼を垂れるように志を隠して去る。苦難の始まり、誤解も受ける段階。"}, {"name": "六二", "text": "明夷、左股を夷る。用て拯うこと馬壮んなれば吉なり。", "meaning": "左の股を傷つけられるが、致命傷ではない段階。すばやく助けに動けば、難を逃れて吉。"}, {"name": "九三", "text": "明夷、南狩に于いてし、其の大首を得たり。疾く貞にすべからず。", "meaning": "暗さの根源（首魁）を討ち取る段階。大本を正せるが、急ぎ過ぎて性急に正してはならない。"}, {"name": "六四", "text": "左腹に入り、明夷の心を獲、于て門庭を出づ。", "meaning": "内側深くに入り込み、暗さの実情を見抜いて、危地を抜け出す段階。早めに離れる。"}, {"name": "六五", "text": "箕子の明夷なり。貞しきに利ろし。", "meaning": "箕子のように、暗君の傍らで才を隠し正気を守る段階。狂を装ってでも志を保てば利あり。"}, {"name": "上六", "text": "明らかならずして晦し。初めには天に登り、後には地に入る。", "meaning": "明るさが尽き、闇に落ちる明夷の極み。高みから一転、地に墜ちる暗君の末路の段階。"}]},
    "風火家人": {"num": 37, "reading": "ふうかかじん", "upper": "巽", "lower": "離", "summary": "火から風が生まれる、家庭・身内を治めるとき。各々が分を守れば調う。", "keywords": ["家庭", "役割", "秩序"], "lines": [{"name": "初九", "text": "家を閑ぐ。悔い亡ぶ。", "meaning": "家の始めに、けじめと垣根を設けて防ぐ。最初に秩序を立て、悔いを未然に防ぐ段階。"}, {"name": "六二", "text": "遂ぐる攸无し。中饋に在り。貞しくして吉。", "meaning": "我を張って事を成そうとせず、内を整え養うことに徹する段階。控えめに支えて吉。"}, {"name": "九三", "text": "家人嗃嗃たり。厲を悔ゆれど吉なり。婦子嘻嘻たれば、終には吝なり。", "meaning": "厳しすぎる家。とがめは残るが秩序は保たれ吉。逆に締まりなく緩めば、最後は乱れる段階。"}, {"name": "六四", "text": "家を富ます。大いに吉なり。", "meaning": "家を豊かに富ませる段階。分をわきまえ、内をよく治めて栄えさせる、大いに吉。"}, {"name": "九五", "text": "王、有家に假る。恤うる勿れ。吉なり。", "meaning": "王が誠をもって家に臨むように、徳で身近を感化する中心の段階。憂えずとも吉。"}, {"name": "上九", "text": "孚有りて威如たれば、終には吉なり。", "meaning": "誠を備え、おのずから備わる威厳で締める家人の極み。まず我が身を正して終に吉の段階。"}]},
    "火澤睽": {"num": 38, "reading": "かたくけい", "upper": "離", "lower": "兌", "summary": "火は上り澤は下る、そむき合い行き違うとき。大事は難しく、小事なら通る。", "keywords": ["不和", "相違", "歩み寄り"], "lines": [{"name": "初九", "text": "悔い亡ぶ。馬を喪うも逐う勿れ、自ら復る。悪人を見るも、咎无し。", "meaning": "背き合いの始め。逃げた馬は追わずとも自ら戻る。気の合わぬ相手も拒まねば咎なき段階。"}, {"name": "九二", "text": "主に巷に遇う。咎无し。", "meaning": "背き合う中、思いがけず路地で味方に出会う段階。略式でも心が通えば、咎はない。"}, {"name": "六三", "text": "輿の曳かるるを見る。其の牛掣かる。其の人、天られ且つ劓らる。初め无くして終わり有り。", "meaning": "車は引き止められ牛も阻まれ、人も傷つく、行き違い極まる段階。始めは苦しいが終わりは結ばれる。"}, {"name": "九四", "text": "睽れて孤なり。元夫に遇う。交孚す。厲うけれど咎无し。", "meaning": "背き合って孤立するが、信ずべき同志に出会い誠を交わす段階。危ういが咎を免れる。"}, {"name": "六五", "text": "悔い亡ぶ。厥の宗、膚を噬む。往くも何の咎あらん。", "meaning": "行き違いが解けていく中心の段階。同志と深く噛み合い結ばれる。進んで何の咎もない。"}, {"name": "上九", "text": "睽れて孤なり。豕の塗を負い、鬼を一車に載するを見る。先には之が弧を張り、後には之が弧を説く。寇に匪ず、婚媾せんとす。往きて雨に遇えば則ち吉なり。", "meaning": "疑心が極まり、泥豚や鬼を見るような妄想に陥る段階。だが誤解が解け、和合の雨に至れば吉。"}]},
    "水山蹇": {"num": 39, "reading": "すいざんけん", "upper": "坎", "lower": "艮", "summary": "山の上に水、足を引きずる難渋のとき。進めば険しい。助けを得て止まる。", "keywords": ["難渋", "障害", "助力"], "lines": [{"name": "初六", "text": "往けば蹇み、来たれば誉れあり。", "meaning": "進めば難渋にはまり、退いて待てば誉れを得る、いちばん下の段階。"}, {"name": "六二", "text": "王臣蹇蹇たり。躬の故に匪ず。", "meaning": "王の臣として、我が身の利でなく大義のために難中を尽くす段階。私心なく苦難に当たる。"}, {"name": "九三", "text": "往けば蹇み、来たりて反る。", "meaning": "進めば険難、退けば内の味方が喜び迎える段階。下の者の支えとなり踏みとどまる。"}, {"name": "六四", "text": "往けば蹇み、来たりて連なる。", "meaning": "単独で進めば難渋。退いて同志と連帯し、力を合わせて難に備える段階。"}, {"name": "九五", "text": "大いに蹇む。朋来たる。", "meaning": "難渋の極みにある中心の段階。だがその誠に応じて、助けの友がやって来る。"}, {"name": "上六", "text": "往けば蹇み、来たりて碩いなり。吉なり。大人を見るに利ろし。", "meaning": "なお進めば難渋だが、退いて大いに成す蹇の極み。賢者を頼れば吉となる段階。"}]},
    "雷水解": {"num": 40, "reading": "らいすいかい", "upper": "震", "lower": "坎", "summary": "雷雨が過ぎ、こわばりが解けるとき。問題が緩み、解放へ向かう。", "keywords": ["解放", "緩和", "赦し"], "lines": [{"name": "初六", "text": "咎无し。", "meaning": "険難がほどけ始めるはじめ。柔と剛が応じ合い、静かに身を保てば咎のない段階。"}, {"name": "九二", "text": "田して三狐を獲、黄矢を得たり。貞しくして吉。", "meaning": "狩りで三匹の狐を捕らえ黄の矢を得るように、惑わす邪を除き中庸を得る段階。正しく吉。"}, {"name": "六三", "text": "負い且つ乗る。寇の至るを致す。貞なれども吝なり。", "meaning": "荷を背負う身で車に乗る、分不相応な段階。身の程を超えて目立てば、盗賊を招き悔いる。"}, {"name": "九四", "text": "而の拇を解く。朋至りて斯に孚あり。", "meaning": "足の親指（まとわりつく小人）を切り離す段階。悪縁を解いてこそ、真の友が来て信じ合う。"}, {"name": "六五", "text": "君子維れ解く有り。吉なり。小人に孚あり。", "meaning": "君子が自ら結び目を解く中心の段階。けじめをつければ吉、小人もそれを見て退き改める。"}, {"name": "上六", "text": "公、用て隼を高墉の上に射る。之を獲て、利ろしからざる无し。", "meaning": "高い城壁の上の隼を射落とすように、害をなす者を機を見て一挙に除く解の極み。"}]},
    "山澤損": {"num": 41, "reading": "さんたくそん", "upper": "艮", "lower": "兌", "summary": "下を減らして上に益す、損なうとき。誠があれば、減らすことが吉となる。", "keywords": ["節減", "献身", "取捨"], "lines": [{"name": "初九", "text": "事を已めて遄かに往く。咎无し。酌んで之を損す。", "meaning": "自分の務めを切り上げ、速やかに上を助けに行く段階。減らす度合いをよく量れば咎なし。"}, {"name": "九二", "text": "貞しきに利ろし。征けば凶なり。損せずして之に益す。", "meaning": "正しさを守るのが利、進めば凶。自分を無理に減らさずとも、あるがままで上を益せる段階。"}, {"name": "六三", "text": "三人行けば則ち一人を損す。一人行けば則ち其の友を得。", "meaning": "三人で行けば一人減り、一人で行けば友を得る。多すぎれば割れ、専一なら結ばれる段階。"}, {"name": "六四", "text": "其の疾を損す。遄かにせしむれば喜び有り。咎无し。", "meaning": "自分の欠点・わずらいを減らす段階。速やかに改めれば喜びがあり、咎はない。"}, {"name": "六五", "text": "或いは之を益す。十朋の亀も違うこと克わず。元いに吉なり。", "meaning": "思いがけず大いに益される中心の段階。占っても外れぬほどの幸運に恵まれ、大いに吉。"}, {"name": "上九", "text": "損せずして之に益す。咎无し。貞しくして吉。往く攸有るに利ろし。臣を得ること家无し。", "meaning": "自らを損なわず、かえって広く人を益す損の極み。私を超えて多くに尽くし、人望を得る段階。"}]},
    "風雷益": {"num": 42, "reading": "ふうらいえき", "upper": "巽", "lower": "震", "summary": "上を減らして下に益す、増し加えるとき。動いて事を進めるに利あり。", "keywords": ["増益", "成長", "善行"], "lines": [{"name": "初九", "text": "用て大いに作すに利ろし。元いに吉にして咎无し。", "meaning": "上から益され、大いに事を起こすにふさわしい始めの段階。大きな成果を上げて咎なし。"}, {"name": "六二", "text": "或いは之を益す。十朋の亀も違うこと克わず。永貞なれば吉。王、用て帝に享す。吉なり。", "meaning": "思いがけぬ大きな益を受ける段階。占っても外れぬ幸運。長く正しさを保てば吉。"}, {"name": "六三", "text": "之を益すに凶事を用う。咎无し。孚ありて中行し、公に告ぐるに圭を用う。", "meaning": "凶事・困難の中でこそ益される段階。誠をもって中道を行き、まごころを示せば咎なし。"}, {"name": "六四", "text": "中行すれば、公に告げて従わる。用て依り遷すに利ろし。", "meaning": "中道を歩む者として上に進言し、聞き入れられる段階。大きな移し替えにも頼られる。"}, {"name": "九五", "text": "孚ありて恵む心あり。問うこと勿れ、元いに吉なり。孚ありて我が徳を恵む。", "meaning": "まごころから人を恵もうとする中心の段階。問うまでもなく大吉。その誠は人からも返される。"}, {"name": "上九", "text": "之を益すこと莫し。或いは之を撃つ。心を立つること恒なし。凶なり。", "meaning": "益を求めるばかりで人に与えぬ益の極み。心が定まらず、ついに攻撃を招く凶の段階。"}]},
    "澤天夬": {"num": 43, "reading": "たくてんかい", "upper": "兌", "lower": "乾", "summary": "澤が天に上り決壊する、決断し断ち切るとき。最後の一陰を退ける危うさを伴う。", "keywords": ["決断", "排除", "明示"], "lines": [{"name": "初九", "text": "前趾に壮んなり。往きて勝たざれば、咎と為る。", "meaning": "足先から勢いづいて進み出る始め。勝算なく突き進み、しくじれば咎となる段階。"}, {"name": "九二", "text": "惕れて号ぶ。莫夜に戎有るも、恤うる勿れ。", "meaning": "警戒を怠らず呼びかける段階。夜に敵が来ても、用心を保っていれば憂えずに済む。"}, {"name": "九三", "text": "頄に壮んなり。凶有り。君子は夬夬たり。独り行きて雨に遇い、濡るるがごとくにして慍るところ有り。咎无し。", "meaning": "顔に怒りを表すほど気負う段階。だが君子は断つべきを断つ。誤解され濡れても、貫けば咎なし。"}, {"name": "九四", "text": "臀に膚无し。其の行くこと次且たり。羊を牽けば悔い亡ぶ。言を聞くも信ぜず。", "meaning": "尻の皮がむけ、進むに進めずためらう段階。人に従い引かれれば悔いは消えるが、忠告を聞かぬ。"}, {"name": "九五", "text": "莧陸夬夬たり。中行すれば咎无し。", "meaning": "やわらかな草を断つように、残る邪を毅然と除く中心の段階。中道を保てば咎なし。"}, {"name": "上六", "text": "号ぶこと无し。終に凶有り。", "meaning": "助けを呼ぶ声も届かず、最後の一陰が除かれる夬の極み。孤立して終わる凶の段階。"}]},
    "天風姤": {"num": 44, "reading": "てんぷうこう", "upper": "乾", "lower": "巽", "summary": "天の下に風、思いがけず出会うとき。一陰が忍び寄る。勢いある誘いには用心。", "keywords": ["遭遇", "誘惑", "警戒"], "lines": [{"name": "初六", "text": "金柅に繋ぐ。貞しくして吉。往く攸有れば、凶を見る。羸豕、孚として蹢躅す。", "meaning": "忍び寄る一陰を金の楔で押さえ止める始め。早く食い止めれば吉、放てば凶という段階。"}, {"name": "九二", "text": "包に魚有り。咎无し。賓に利ろしからず。", "meaning": "包みの中に魚を収め、ひそかに抑え込む段階。自分の手元で制すれば咎なし。広く及ぼすのは不利。"}, {"name": "九三", "text": "臀に膚无し。其の行くこと次且たり。厲うけれど、大いなる咎无し。", "meaning": "尻の皮がむけて落ち着かず、進みあぐねる段階。危ういが、慎んで動かねば大過には至らぬ。"}, {"name": "九四", "text": "包に魚无し。凶を起こす。", "meaning": "包みから魚が失われる段階。手元の人心が離れ去り、それが災いを引き起こす。"}, {"name": "九五", "text": "杞を以て瓜を包む。章を含む。天より隕つること有り。", "meaning": "高い杞の木で瓜を包むように、徳を内に秘めて下を覆い守る中心の段階。天与の幸いが下る。"}, {"name": "上九", "text": "其の角に姤う。吝なり。咎无し。", "meaning": "角の先で出会う、よそよそしく高ぶった姤の極み。人と打ち解けられず悔いるが、咎はない段階。"}]},
    "澤地萃": {"num": 45, "reading": "たくちすい", "upper": "兌", "lower": "坤", "summary": "澤が地に集まる、人や物が集うとき。中心と誠があれば、よく集まり通る。", "keywords": ["集合", "団結", "求心"], "lines": [{"name": "初六", "text": "孚有れども終わらず。乃ち乱れ乃ち萃まる。号べば、一握りに笑いと為る。恤うる勿れ。往きて咎无し。", "meaning": "集まろうとする誠が揺らぎ、迷い乱れる始め。心を定めて呼びかければ、笑いに変わる段階。"}, {"name": "六二", "text": "引かれて吉。咎无し。孚なれば乃ち禴を用うるに利ろし。", "meaning": "誠ある相手に引かれて、自然に集い結ばれる段階。質素な真心の供えでも通じ、吉。"}, {"name": "六三", "text": "萃如たり嗟如たり。利ろしき攸无し。往けば咎无し。小しく吝なり。", "meaning": "集まりたいのに応じる相手がなく、嘆く段階。当ては外れるが、上に進み結べば咎は小さい。"}, {"name": "九四", "text": "大いに吉にして咎无し。", "meaning": "多くの人を集めまとめる要の段階。私心なく公のために尽くせば、大いに吉で咎もない。"}, {"name": "九五", "text": "萃まるに位有り。咎无し。孚とせられず。元永貞なれば、悔い亡ぶ。", "meaning": "正しい地位のもとに人を集める中心の段階。まだ信を得きらぬ者には、長く誠を保てば悔い消ゆ。"}, {"name": "上六", "text": "齎咨涕洟す。咎无し。", "meaning": "集いに加われず、嘆き涙する萃の極み。孤立を憂え深く反省すれば、咎を免れる段階。"}]},
    "地風升": {"num": 46, "reading": "ちふうしょう", "upper": "坤", "lower": "巽", "summary": "地中から木が伸びる、昇り進むとき。順を追って上れば、大いに通る。", "keywords": ["上昇", "成長", "着実"], "lines": [{"name": "初六", "text": "允かに升る。大いに吉なり。", "meaning": "下にありながら、上に信じられて素直に昇り始める段階。信を得て伸びる、大いに吉。"}, {"name": "九二", "text": "孚なれば乃ち禴を用うるに利ろし。咎无し。", "meaning": "質素でも誠さえあれば通じる段階。飾らぬ真心で上と結べば、咎のない昇りの段階。"}, {"name": "九三", "text": "虚邑に升る。", "meaning": "人のいない邑に入るように、障りなくすらすらと昇り進む段階。妨げなく上がっていく。"}, {"name": "六四", "text": "王、用て岐山に亨す。吉にして咎无し。", "meaning": "王が聖山に誠を捧げるように、へりくだって上に従い順う段階。吉にして咎なし。"}, {"name": "六五", "text": "貞しくして吉。階を升る。", "meaning": "正しさを保ち、階段を一段ずつ着実に昇る中心の段階。順を踏んで高みに至り吉。"}, {"name": "上六", "text": "冥升なり。息まざるの貞に利ろし。", "meaning": "暗がりをなお昇り続ける升の極み。止め時を失う危うさだが、内なる修養に向ければ利ある段階。"}]},
    "澤水困": {"num": 47, "reading": "たくすいこん", "upper": "兌", "lower": "坎", "summary": "澤の水が漏れ尽きる、行き詰まり苦しむとき。言葉が通じにくい。耐えて通す。", "keywords": ["困窮", "逆境", "節操"], "lines": [{"name": "初六", "text": "臀、株木に困しむ。幽谷に入り、三歳まで覿えず。", "meaning": "切り株に腰かけて苦しむように、出口の見えぬ谷に入り込む、困窮の始まりの段階。"}, {"name": "九二", "text": "酒食に困しむ。朱紱方に来たる。用て享祀するに利ろし。征けば凶なり。咎无し。", "meaning": "酒食に不自由する困窮の中、上からの招き（朱紱）が来かける段階。動けば凶、誠を保てば咎なし。"}, {"name": "六三", "text": "石に困しみ、蒺藜に拠る。其の宮に入りて、其の妻を見ず。凶なり。", "meaning": "石に阻まれ茨に拠る、進退きわまる段階。帰っても頼る妻に会えぬ、寄る辺なき凶。"}, {"name": "九四", "text": "来たること徐徐たり。金車に困しむ。吝なれど、終わり有り。", "meaning": "助けに向かうのが遅れ、金の車（地位ある障り）に阻まれる段階。悔いはあるが、終には結ばれる。"}, {"name": "九五", "text": "劓られ刖らる。赤紱に困しむ。乃ち徐ろに説び有り。用て祭祀するに利ろし。", "meaning": "上下から傷つけられ、高位ゆえに苦しむ中心の段階。やがて徐々に救いが来る。誠を尽くせば吉。"}, {"name": "上六", "text": "葛藟に困しみ、臲卼たり。動けば悔い有りと曰う。悔ゆる有れば、征きて吉なり。", "meaning": "蔓草に絡まれ、ぐらつき揺れる困の極み。動けば悔いると思い込むが、悔い改めて動けば吉の段階。"}]},
    "水風井": {"num": 48, "reading": "すいふうせい", "upper": "坎", "lower": "巽", "summary": "井戸のように、変わらず人を養うとき。場所は変われど、井戸の徳は変わらない。", "keywords": ["不変の徳", "供給", "養い"], "lines": [{"name": "初六", "text": "井泥みて食らわれず。旧井に禽无し。", "meaning": "井戸の底が泥み、飲めず、古井戸には鳥も寄らぬ段階。荒れて用をなさない、いちばん下。"}, {"name": "九二", "text": "井、谷ぎて鮒に射ぐ。甕敝れて漏る。", "meaning": "澄んだ水が下の小魚にしか及ばず、汲む甕も壊れて漏れる段階。徳はあれど活かされぬ。"}, {"name": "九三", "text": "井渫えども食らわれず。我が心の惻みと為す。用て汲むべし。王明らかなれば、並びに其の福を受く。", "meaning": "井戸を浚っても汲まれない段階。澄んだ才が用いられず惜しまれる。上が明なら共に福を受ける。"}, {"name": "六四", "text": "井甃む。咎无し。", "meaning": "井戸の内壁を石で整え修める段階。今は人を潤さずとも、自らを整えるに専心して咎なし。"}, {"name": "九五", "text": "井冽くして寒泉食らわる。", "meaning": "井戸の水が清く澄み、冷たい泉として皆に飲まれる中心の段階。徳が広く人に行き渡る。"}, {"name": "上六", "text": "井収めて幕う勿れ。孚有りて元いに吉なり。", "meaning": "汲み上げた井戸に蓋をせず、誰にでも開く井の極み。誠をもって広く施し、大いに吉の段階。"}]},
    "澤火革": {"num": 49, "reading": "たくかかく", "upper": "兌", "lower": "離", "summary": "澤と火が相せめぐ、革まり改めるとき。時が満ちて信を得れば、悔いは消える。", "keywords": ["変革", "刷新", "改める"], "lines": [{"name": "初九", "text": "鞏むるに黄牛の革を用う。", "meaning": "黄牛の革で固く縛るように、まだ動かず堅く守る改革の始め。時が来ていない段階。"}, {"name": "六二", "text": "已の日にして乃ち之を革む。征けば吉にして咎无し。", "meaning": "時が満ちて、いよいよ改める段階。機が熟してから動けば、進んで吉、咎もない。"}, {"name": "九三", "text": "征けば凶なり。貞なれども厲うし。革言三たび就れば、孚あり。", "meaning": "急いで改めれば凶、危うい段階。変革の議論を三度重ね、衆議が定まってこそ信を得る。"}, {"name": "九四", "text": "悔い亡ぶ。孚有りて命を改む。吉なり。", "meaning": "悔いの消える段階。誠が満ち、信を得て根本（命）を改める。時宜にかなった変革で吉。"}, {"name": "九五", "text": "大人虎変す。未だ占わずして孚あり。", "meaning": "大人が虎の毛が美しく変わるように、鮮やかに改める中心の段階。占うまでもなく信を得る。"}, {"name": "上六", "text": "君子豹変す。小人は面を革む。征けば凶なり。居て貞なれば吉。", "meaning": "君子は豹の斑のように細部まで改め、小人は顔つきだけ従う革の極み。なお進めば凶、留まれば吉。"}]},
    "火風鼎": {"num": 50, "reading": "かふうてい", "upper": "離", "lower": "巽", "summary": "食をととのえる鼎の象。新しきを煮て養い、立て直すとき。大いに吉。", "keywords": ["革新", "滋養", "安定"], "lines": [{"name": "初六", "text": "鼎、趾を顛にす。否を出すに利ろし。妾を得て其の子を以にす。咎无し。", "meaning": "鼎をひっくり返して古い澱を出すように、まず汚れを払う始めの段階。下のものでも用いて咎なし。"}, {"name": "九二", "text": "鼎、実有り。我が仇に疾有り。我に即くこと能わず。吉なり。", "meaning": "鼎に中身が満ちる充実の段階。妬む相手も近づけず、中身を守り通せて吉。"}, {"name": "九三", "text": "鼎、耳革まり、其の行塞がる。雉の膏食らわれず。方に雨ふりて悔いを虧き、終には吉なり。", "meaning": "鼎の耳が変わり持ち運べず、ごちそうが食べられぬ段階。だが時が和し、終には用いられて吉。"}, {"name": "九四", "text": "鼎、足を折る。公の餗を覆す。其の形渥たり。凶なり。", "meaning": "鼎の足が折れて中身をぶちまける段階。荷に耐えぬ者が重任を担い、大失敗する凶。"}, {"name": "六五", "text": "鼎、黄耳金鉉なり。貞しきに利ろし。", "meaning": "鼎に黄金の耳と取っ手が備わる中心の段階。中庸と剛健を兼ね、よく中身を担い動かせる。"}, {"name": "上九", "text": "鼎、玉鉉なり。大いに吉にして利ろしからざる无し。", "meaning": "鼎に玉の取っ手が備わる鼎の極み。剛と温潤を兼ね、調和の極まる、大いに吉の段階。"}]},
    "震為雷": {"num": 51, "reading": "しんいらい", "upper": "震", "lower": "震", "summary": "雷が重なり轟く、衝撃と発奮のとき。驚いても動じず保てば通る。", "keywords": ["衝撃", "発奮", "畏れ"], "lines": [{"name": "初九", "text": "震來りて虩虩たり。後に笑言啞啞たり。吉なり。", "meaning": "雷鳴に驚き怖れるが、慎みを学んで後に和らぎ笑える段階。畏れを糧にできる、吉の始め。"}, {"name": "六二", "text": "震來りて厲うし。億ばくの貝を喪う。九陵に躋る。逐う勿れ、七日にして得ん。", "meaning": "激しい衝撃で大事な財を失う段階。高みに逃れ、追わずに待てば、やがて自ずと取り戻せる。"}, {"name": "六三", "text": "震蘇蘇たり。震うて行けば眚无し。", "meaning": "雷に脅えて落ち着かぬ段階。だがその畏れに促されて慎んで動けば、災いを免れる。"}, {"name": "九四", "text": "震、遂に泥む。", "meaning": "衝撃の中で泥にはまり込み、奮い立てず沈滞する段階。剛が陰に挟まれ動けない。"}, {"name": "六五", "text": "震、往來すること厲うし。億ばくに喪うこと无し。事有り。", "meaning": "衝撃が行き来して危うい中心の段階。だが中を守れば失うものはなく、為すべき務めは保てる。"}, {"name": "上六", "text": "震、索索たり。視ること矍矍たり。征けば凶なり。震、其の躬に于いてせずして、其の隣に于いてす。咎无し。婚媾に言有り。", "meaning": "衝撃に怯えきり、目をきょろつかせる震の極み。動けば凶。だが他人の災いを見て早く戒めれば咎なし。"}]},
    "艮為山": {"num": 52, "reading": "ごんいさん", "upper": "艮", "lower": "艮", "summary": "山が重なり動かぬ、止まるとき。止まるべきところに止まれば、咎はない。", "keywords": ["静止", "抑制", "安定"], "lines": [{"name": "初六", "text": "其の趾に艮まる。咎无し。永貞に利ろし。", "meaning": "足の段階で早くも止まる。動き出す前に踏みとどまれば、咎なき止まりの始め。"}, {"name": "六二", "text": "其の腓に艮まる。其の随うを拯わず。其の心快からず。", "meaning": "ふくらはぎで止まる段階。上に従って動かざるを得ず、思うように救えず、心が晴れない。"}, {"name": "九三", "text": "其の限に艮まる。其の夤を列く。厲うくして心を薫く。", "meaning": "腰で無理に断ち止める段階。上下を裂くように強いて止め、危うく心を焦がす。"}, {"name": "六四", "text": "其の身に艮まる。咎无し。", "meaning": "我が身全体を静かに止める段階。私欲を抑え、おのれを安んじて保てば、咎はない。"}, {"name": "六五", "text": "其の輔に艮まる。言、序有り。悔い亡ぶ。", "meaning": "あご（口）を慎んで止める中心の段階。言葉に筋目を保てば、口の過ちが消えていく。"}, {"name": "上九", "text": "敦く艮まる。吉なり。", "meaning": "手厚く誠実に、終わりまで止まるべきに止まる艮の極み。静止を全うして吉の段階。"}]},
    "風山漸": {"num": 53, "reading": "ふうざんぜん", "upper": "巽", "lower": "艮", "summary": "山の上に木、少しずつ進むとき。順序を踏んで漸進すれば吉。", "keywords": ["漸進", "順序", "着実"], "lines": [{"name": "初六", "text": "鴻、干に漸む。小子厲うし。言有れど、咎无し。", "meaning": "渡り鳥が水際に進み着く始め。未熟な身には危うく、とがめの声もあるが、咎には至らぬ段階。"}, {"name": "六二", "text": "鴻、磐に漸む。飲食衎衎たり。吉なり。", "meaning": "鳥が安らかな岩場に進む段階。落ち着いて飲食を楽しむ、安定した進みの吉。"}, {"name": "九三", "text": "鴻、陸に漸む。夫征けば復らず。婦孕めども育てず。凶なり。寇を禦ぐに利ろし。", "meaning": "高地に進みすぎる段階。順序を外れて突出すれば、夫は帰らず妻は育てぬような凶。守りには利あり。"}, {"name": "六四", "text": "鴻、木に漸む。或いは其の桷を得。咎无し。", "meaning": "水鳥が止まりにくい木に進む段階。だが平らな枝を得るように、危うい中で安住を見出し咎なし。"}, {"name": "九五", "text": "鴻、陵に漸む。婦三歳まで孕まず。終に之に勝つこと莫し。吉なり。", "meaning": "鳥が高い丘に進む中心の段階。隔てられて久しく結ばれずとも、誰にも妨げられず終に結ばれ吉。"}, {"name": "上九", "text": "鴻、陸に漸む。其の羽、用て儀と為すべし。吉なり。", "meaning": "鳥が高みに進み着き、その羽が手本・飾りとなる漸の極み。順を全うし、人の模範となる吉の段階。"}]},
    "雷澤帰妹": {"num": 54, "reading": "らいたくきまい", "upper": "震", "lower": "兌", "summary": "澤の上に雷、順を外れて嫁ぐ象。情に任せて進めば凶。立場をわきまえるとき。", "keywords": ["不正規", "分を守る", "慎み"], "lines": [{"name": "初九", "text": "妹を帰がしむに娣を以てす。跛にして能く履む。征けば吉なり。", "meaning": "正妻でなく添い添えとして嫁ぐ始め。低い立場でも、分を守って務めれば進んで吉の段階。"}, {"name": "九二", "text": "眇にして能く視る。幽人の貞に利ろし。", "meaning": "片目でもよく見るように、不遇でも内に明を保つ段階。人目につかず静かに正しくあれば利あり。"}, {"name": "六三", "text": "妹を帰がしむに須ちて、反りて娣を以てす。", "meaning": "高望みして時を待つうち、かえって添い添えに格下げされる段階。分を超えた望みがしぼむ。"}, {"name": "九四", "text": "妹を帰がしむに期を愆る。帰ぐを遅らするに時有り。", "meaning": "嫁ぐ時期を過ぎても、あえて待つ段階。安売りせず、ふさわしい時と相手を待てば、なお時は来る。"}, {"name": "六五", "text": "帝乙、妹を帰がしむ。其の君の袂は、其の娣の袂の良きに如かず。月、望に幾ければ吉なり。", "meaning": "高貴な身でありながら、装いを誇らず質素に嫁ぐ中心の段階。満月手前のように、控えめさで吉。"}, {"name": "上六", "text": "女、筐を承くるも実无し。士、羊を刲くも血无し。利ろしき攸无し。", "meaning": "中身のない筐を捧げ、血の出ぬ羊を割く、形だけの帰妹の極み。実を欠き、何の益もない段階。"}]},
    "雷火豊": {"num": 55, "reading": "らいかほう", "upper": "震", "lower": "離", "summary": "雷と火が盛んな、豊かさの極みのとき。盛りは美しいが、やがて傾く。", "keywords": ["隆盛", "充実", "陰り"], "lines": [{"name": "初九", "text": "其の配主に遇う。旬なれども咎无し。往けば尚ばるること有り。", "meaning": "豊かさの始め、対等の相手に出会う。互いに均しく釣り合い、咎なく、進めば称えられる段階。"}, {"name": "六二", "text": "其の蔀を豊かにす。日中に斗を見る。往けば疑疾を得。孚有りて発若たれば吉なり。", "meaning": "覆いが厚く、真昼に北斗が見えるほど暗む段階。進めば疑われるが、誠で心を開けば吉。"}, {"name": "九三", "text": "其の沛を豊かにす。日中に沫を見る。其の右肱を折る。咎无し。", "meaning": "覆いがさらに厚く、真昼に小星が見える段階。右腕を折るように頼りを失うが、無理せねば咎なし。"}, {"name": "九四", "text": "其の蔀を豊かにす。日中に斗を見る。其の夷主に遇う。吉なり。", "meaning": "なお暗さの中だが、対等の同志に巡り合う段階。覆いを破る助けを得て、吉に転じる。"}, {"name": "六五", "text": "章を来たす。慶誉有り。吉なり。", "meaning": "隠れていた才ある者を招き寄せる中心の段階。賢を用いて明を取り戻し、慶びと誉れを得て吉。"}, {"name": "上六", "text": "其の屋を豊かにす。其の家を蔀う。其の戸を闚えば、闃として其れ人无し。三歳まで覿えず。凶なり。", "meaning": "家を立派にしすぎて覆い隠し、人気が絶える豊の極み。盛りに驕り孤立する、凶の段階。"}]},
    "火山旅": {"num": 56, "reading": "かざんりょ", "upper": "離", "lower": "艮", "summary": "山の上に火、留まらず移ろう旅のとき。寄る辺なき身。慎めば小さく通る。", "keywords": ["旅", "不安定", "慎み"], "lines": [{"name": "初六", "text": "旅、瑣瑣たり。斯れ其の災を取る所なり。", "meaning": "旅の身でつまらぬ事にこせつく始め。卑屈に小利を求め、自ら災いを招く段階。"}, {"name": "六二", "text": "旅、次に即く。其の資を懐にし、童僕の貞を得たり。", "meaning": "旅で落ち着ける宿を得て、路銀を持ち、忠実な従者にも恵まれる段階。寄る辺を得て安らぐ。"}, {"name": "九三", "text": "旅、其の次を焚く。其の童僕の貞を喪う。厲うし。", "meaning": "旅先で宿を焼き、忠実な従者まで失う段階。高ぶり過ぎて寄る辺と信を失う、危うい段階。"}, {"name": "九四", "text": "旅、于に処る。其の資斧を得たり。我が心快からず。", "meaning": "仮の落ち着き先と路銀・斧（手立て）を得る段階。一応安んじるが、本拠でなく心は晴れない。"}, {"name": "六五", "text": "雉を射て一矢にして亡う。終に以て誉れあり命あり。", "meaning": "雉を射て一矢は失うが獲物は得る中心の段階。小さな代償で信を得、ついに誉れと地位を得る。"}, {"name": "上九", "text": "鳥、其の巣を焚く。旅人、先には笑い、後には號咷す。牛を易に喪う。凶なり。", "meaning": "鳥が巣を焼かれるように、高みで驕った旅の極み。先に笑い後に泣き、柔順さを失って凶の段階。"}]},
    "巽為風": {"num": 57, "reading": "そんいふう", "upper": "巽", "lower": "巽", "summary": "風が重なり、すみずみに入り込むとき。へりくだり従えば、小さく通る。", "keywords": ["浸透", "柔順", "順応"], "lines": [{"name": "初六", "text": "進退す。武人の貞に利ろし。", "meaning": "風のように、進むか退くか定まらず迷う始め。優柔の段階。武人のような決断と正しさが要る。"}, {"name": "九二", "text": "牀下に巽う。史巫を用うること紛若たれば、吉にして咎无し。", "meaning": "寝台の下までへりくだり伏す段階。度を越えた卑下だが、誠を尽くして祈るほどに通じれば吉。"}, {"name": "九三", "text": "頻りに巽う。吝なり。", "meaning": "何度もためらい従い直す段階。決めきれず、しぶしぶ繰り返し従って悔いる。"}, {"name": "六四", "text": "悔い亡ぶ。田して三品を獲。", "meaning": "悔いの消える段階。柔順に従いつつ功を立て、狩りで三種の獲物を得るように、よく成果を上げる。"}, {"name": "九五", "text": "貞しくして吉。悔い亡ぶ。利ろしからざる无し。初め无くして終わり有り。庚に先だつこと三日、庚に後るること三日なれば吉なり。", "meaning": "正しさを保ち、よく改め命じる中心の段階。始めは整わずとも終には成る。前後をよく慮れば吉。"}, {"name": "上九", "text": "牀下に巽う。其の資斧を喪う。貞なれども凶なり。", "meaning": "寝台の下まで卑下しきり、断つべき力（斧）まで失う巽の極み。へつらい過ぎて自立を失う凶の段階。"}]},
    "兌為澤": {"num": 58, "reading": "だいたく", "upper": "兌", "lower": "兌", "summary": "澤が連なり、よろこび語らうとき。和やかさで通るが、正しさを失わぬこと。", "keywords": ["悦び", "交流", "和"], "lines": [{"name": "初九", "text": "和らぎて兌ぶ。吉なり。", "meaning": "私心なく、和やかに人と喜び合う始め。誰にもおもねらず、穏やかに通じ合って吉の段階。"}, {"name": "九二", "text": "孚ありて兌ぶ。吉なり。悔い亡ぶ。", "meaning": "まことをもって喜び合う段階。誠が伴うから、悦びに溺れず、悔いも消えて吉。"}, {"name": "六三", "text": "来たり兌ぶ。凶なり。", "meaning": "こちらから取り入り、媚びて喜ばせようとする段階。誠を欠いたおもねりは凶を招く。"}, {"name": "九四", "text": "商り兌ぶ。未だ寧からず。介疾なれば喜び有り。", "meaning": "どちらの悦びに付くか思案して定まらぬ段階。きっぱり邪を退け善に付けば、喜びが来る。"}, {"name": "九五", "text": "剝に孚あり。厲うきこと有り。", "meaning": "削り取ろうとする小人を信じてしまう中心の段階。甘い相手を信じすぎれば、危うさが潜む。"}, {"name": "上六", "text": "引きて兌ぶ。", "meaning": "人を引き込んで悦びにふけろうとする兌の極み。果てなく快を求め、定まりを欠く段階。"}]},
    "風水渙": {"num": 59, "reading": "ふうすいかん", "upper": "巽", "lower": "坎", "summary": "風が水を散らす、こわばりが解け散るとき。滞りをほどき、人心を集め直す。", "keywords": ["発散", "離散", "再結集"], "lines": [{"name": "初六", "text": "用て拯うに馬壮んなれば吉なり。", "meaning": "散り始めの初め。力ある助け（壮んな馬）を頼り、早めに手を打てば、離散を防げて吉の段階。"}, {"name": "九二", "text": "渙るとき其の机に奔る。悔い亡ぶ。", "meaning": "散り散る時、寄るべき拠り所（机）に駆け寄る段階。頼れる支えに身を寄せれば、悔いが消える。"}, {"name": "六三", "text": "其の躬を渙らす。悔い无し。", "meaning": "わが身へのこだわり（私心）を散らし去る段階。自分を捨てて大事に向かえば、悔いはない。"}, {"name": "六四", "text": "其の羣を渙らす。元いに吉なり。渙るとき丘有り。夷の思う所に匪ず。", "meaning": "私的な徒党を散らし、より大きく結び直す段階。偏った群れを解いて大吉。"}, {"name": "九五", "text": "渙るとき其の大号を汗のごとくにす。渙るとき王居す。咎无し。", "meaning": "汗のように行き渡る大号令を発し、散じた人心をまとめ直す中心の段階。中心が定まり咎なし。"}, {"name": "上九", "text": "其の血を渙らす。去り逖く出づれば、咎无し。", "meaning": "傷つけ合う危うさ（血）を散らし去る渙の極み。害から遠く離れ出れば、咎を免れる段階。"}]},
    "水澤節": {"num": 60, "reading": "すいたくせつ", "upper": "坎", "lower": "兌", "summary": "澤の上に水、ほどよく区切る節度のとき。度を保てば通る。苦しい節制は続かない。", "keywords": ["節度", "区切り", "適度"], "lines": [{"name": "初九", "text": "戸庭を出でず。咎无し。", "meaning": "戸口の庭からも出ず、慎んで控える始め。出るべきでない時を見極めて止まれば、咎なし。"}, {"name": "九二", "text": "門庭を出でず。凶なり。", "meaning": "出るべき時なのに門の庭からも出ず、機を逸する段階。度を越えた引きこもりは凶を招く。"}, {"name": "六三", "text": "節せざれば、則ち嗟若たり。咎无し。", "meaning": "節度を保てず、後で嘆くことになる段階。だが自ら招いたと悟れば、人を恨まず咎を免れる。"}, {"name": "六四", "text": "節に安んず。亨る。", "meaning": "無理なく、自然に節度に安んじる段階。身の丈に合った限度を守り、すらすら通る。"}, {"name": "九五", "text": "甘んじて節す。吉なり。往きて尚ばるること有り。", "meaning": "進んで心地よく節度を守る中心の段階。自らも喜び人にも及ぼす、模範となる吉。"}, {"name": "上六", "text": "苦節す。貞なれば凶なり。悔い亡ぶ。", "meaning": "苦しいほど厳しく締めつける節の極み。それを貫けば凶。だが行き過ぎを悔い改めれば悔い消ゆ。"}]},
    "風澤中孚": {"num": 61, "reading": "ふうたくちゅうふ", "upper": "巽", "lower": "兌", "summary": "内に誠が満ちるとき。まことは魚や豚にまで及ぶ。信があれば大事も渡れる。", "keywords": ["誠", "信頼", "真心"], "lines": [{"name": "初九", "text": "虞れば吉なり。它有れば燕からず。", "meaning": "誠を交わす初め、相手をよく見定めれば吉。心が他へ移れば、安らげない段階。"}, {"name": "九二", "text": "鳴く鶴陰に在り。其の子之に和す。我に好爵有り。吾れ爾と之を靡くせん。", "meaning": "陰で鳴く鶴に子が和すように、誠が見えぬ所でも響き合う段階。真心は、隔てなく通じ分かち合える。"}, {"name": "六三", "text": "敵を得たり。或いは鼓し或いは罷め、或いは泣き或いは歌う。", "meaning": "頼る相手次第で、進んだり止まったり泣いたり歌ったり、心が定まらぬ段階。誠が外に振り回される。"}, {"name": "六四", "text": "月、望に幾し。馬匹亡う。咎无し。", "meaning": "満月手前のように誠が満ちる段階。馬の片割れを捨てるように、私的な徒党を絶ち上に専心して咎なし。"}, {"name": "九五", "text": "孚ありて攣如たり。咎无し。", "meaning": "誠をもって人々の心を固く結び合わせる中心の段階。まことが要となり、皆をつなぎ留めて咎なし。"}, {"name": "上九", "text": "翰音天に登る。貞なれども凶なり。", "meaning": "鶏の声だけが天に届くような、実の伴わぬ評判が上滑りする中孚の極み。虚名を貫けば凶の段階。"}]},
    "雷山小過": {"num": 62, "reading": "らいざんしょうか", "upper": "震", "lower": "艮", "summary": "山の上に雷、少し度を過ぎるとき。小事なら通るが、大事を望むのは不可。", "keywords": ["小さな逸脱", "控えめ", "慎重"], "lines": [{"name": "初六", "text": "飛鳥、以て凶なり。", "meaning": "分をわきまえず、鳥が高く飛び上がるように出過ぎる始め。身の程を超えて動き、凶を招く段階。"}, {"name": "六二", "text": "其の祖を過ぎ、其の妣に遇う。其の君に及ばず、其の臣に遇う。咎无し。", "meaning": "行き過ぎても、適度なところで踏みとどまり、分にかなう相手に落ち着く段階。出過ぎず咎なし。"}, {"name": "九三", "text": "防ぎ過ぎず。之に従いて或いは戕わる。凶なり。", "meaning": "用心しすぎぬ余り、害に備えを怠る段階。油断して相手に従えば、傷つけられかねない凶。"}, {"name": "九四", "text": "咎无し。過ぎずして之に遇う。往けば厲うし。必ず戒めよ。永貞を用うる勿れ。", "meaning": "出過ぎず、ほどよく事に当たれば咎なき段階。進めば危うい。必ず戒め、強情を張ってはならない。"}, {"name": "六五", "text": "密雲あれども雨ふらず、我が西郊よりす。公、弋して彼の穴に在るを取る。", "meaning": "厚い雲はあれど恵みの雨に至らぬ段階。高みにありながら力及ばず、賢を求めて穴の人を取る。"}, {"name": "上六", "text": "遇わずして之に過ぐ。飛鳥之を離る。凶なり。是れを災眚と謂う。", "meaning": "ほどよさを通り越して、行き過ぎる小過の極み。鳥が網にかかるように、度を越して災いを招く凶。"}]},
    "水火既済": {"num": 63, "reading": "すいかきせい", "upper": "坎", "lower": "離", "summary": "水と火が整い、ことが既に成ったとき。完成の安らぎの裏で、乱れの兆しが始まる。", "keywords": ["完成", "均衡", "油断戒め"], "lines": [{"name": "初九", "text": "其の輪を曳く。其の尾を濡らす。咎无し。", "meaning": "渡り終えた直後、車輪を引きとどめ尾を濡らすように、勢いを抑え慎む始め。出過ぎねば咎なし。"}, {"name": "六二", "text": "婦、其の茀を喪う。逐う勿れ。七日にして得ん。", "meaning": "婦人が車の覆いを失うように、一時的に頼みを失う段階。追わず構えていれば、自ずと戻る。"}, {"name": "九三", "text": "高宗鬼方を伐つ。三年にして之に克つ。小人は用うる勿れ。", "meaning": "名君が辺境を平定するのに三年を要する段階。大事は長く力を要し、未熟な者に委ねてはならない。"}, {"name": "六四", "text": "繻に衣袽有り。終日戒む。", "meaning": "舟の水漏れに備えてぼろ布を用意し、終日警戒する段階。完成の裏のほころびに備える。"}, {"name": "九五", "text": "東隣の牛を殺すは、西隣の禴祭の実に福を受くるに如かず。", "meaning": "盛大な供え（東隣の牛）より、質素でも誠ある祭り（西隣）が福を受ける中心の段階。実を尊ぶ。"}, {"name": "上六", "text": "其の首を濡らす。厲うし。", "meaning": "渡りきった油断から、頭まで水に浸かる既済の極み。成った後に気を緩め、危うさに陥る段階。"}]},
    "火水未済": {"num": 64, "reading": "かすいびせい", "upper": "離", "lower": "坎", "summary": "火と水が定まらず、まだ済んでいないとき。あと一歩。詰めを誤れば実らない。", "keywords": ["未完成", "あと一歩", "慎重"], "lines": [{"name": "初六", "text": "其の尾を濡らす。吝なり。", "meaning": "渡り始めにいきなり尾を濡らすように、力を量らず動く始め。見込み違いで悔いる段階。"}, {"name": "九二", "text": "其の輪を曳く。貞しくして吉。", "meaning": "車輪を引きとどめ、はやる勢いを抑える段階。逸らず正しさを保って進めば吉となる。"}, {"name": "六三", "text": "未だ済らず。征けば凶なり。大川を渉るに利ろし。", "meaning": "まだ渡りきれぬ段階。力足らぬまま進めば凶。だが時を得て大事に踏み出すには利がある。"}, {"name": "九四", "text": "貞しくして吉。悔い亡ぶ。震いて用て鬼方を伐つ。三年にして大国に賞有り。", "meaning": "正しさを保てば吉、悔い消ゆ。奮い立って辺境を討ち、三年かけて大功を立て報われる段階。"}, {"name": "六五", "text": "貞しくして吉。悔い无し。君子の光あり。孚有りて吉なり。", "meaning": "正しさを保って吉、悔いなき中心の段階。君子の徳が光を放ち、誠が満ちて吉となる。"}, {"name": "上九", "text": "孚有りて酒を飲む。咎无し。其の首を濡らせば、孚ありて是を失う。", "meaning": "完成を前に誠をもって楽しむ未済の極み。節度を保てば咎なし。だが度を越して溺れれば、信を失う段階。"}]},
}
